window.MUC_QUESTION_BANK=[{"id": "q-5498caf45ab49a", "type": "mcq", "prompt": "Why is the security boundary of a smart camera larger than the physical camera itself?", "answerHTML": "<p>B. Because security also depends on networks, cloud services, applications, and users<\/p><p>أمن الكاميرا بيعتمد كمان على الشبكة والخدمات والتطبيق والمستخدمين.<\/p>", "group": "4", "lecture": "1", "href": "lesson.html#slide-4", "options": ["Because cameras always have unlimited processing power", "Because security also depends on networks, cloud services, applications, and users", "Because a camera does not contain software", "Because only physical access matters"], "correct": 1, "explanation": "أمن الكاميرا بيعتمد كمان على الشبكة والخدمات والتطبيق والمستخدمين.", "persist": "q0"}, {"id": "q-d876300ecfc35a", "type": "blank", "prompt": "A smart camera's security must consider the complete device-service _______.", "answerHTML": "<p><span dir=\"ltr\" style=\"display:block;margin:8px 0\"><span><strong>Answer: Ecosystem<\/strong><\/span><\/span><span dir=\"rtl\" style=\"display:block;margin:8px 0\">يعني النظام الكامل بكل أجزائه المرتبطة ببعض.<\/span><\/p>", "group": "4", "lecture": "1", "href": "lesson.html#slide-4"}, {"id": "q-7e936b97bef649", "type": "case", "prompt": "Smart Camera — Cloud Service Outage", "answerHTML": "<p><span dir=\"ltr\" style=\"display:block;margin:8px 0\"><span><strong>Correct Answer (English):<\/strong><\/span><\/span><span dir=\"ltr\" style=\"display:block;margin:8px 0\">The affected component is the Cloud Service. The camera depends on remote services for certain functions, so a cloud failure may interrupt access to recordings even when the camera hardware is functioning.<\/span><span dir=\"rtl\" style=\"display:block;margin:8px 0\"><span><strong>الشرح بالعربي:<\/strong><\/span><\/span><span dir=\"rtl\" style=\"display:block;margin:8px 0\">الكاميرا شغالة، لكن الخدمة اللي بتعتمد عليها للوصول للتسجيلات مش متاحة. إذن المشكلة في <span><strong>Dependency<\/strong><\/span> خارج الجهاز نفسه.<\/span><span dir=\"ltr\" style=\"display:block;margin:8px 0\"><span><strong>Exam Keywords:<\/strong><\/span> Cloud Service, Remote Access, Dependency, Service Unavailability.<\/span><\/p>", "group": "4", "lecture": "1", "href": "lesson.html#slide-4", "context": "A smart security camera is functioning correctly, but its owner cannot access recordings because the remote cloud service is unavailable.", "questionsHTML": "<p dir=\"ltr\">Question: Identify the affected ecosystem component and explain why the camera may be affected even though its hardware is functioning.<\/p>"}, {"id": "q-cd05e03cb5c292", "type": "mcq", "prompt": "Which component may aggregate data from multiple local IoT devices?", "answerHTML": "<p>B. Gateway / Edge<\/p><p>Gateway / Edge ممكن يجمع بيانات عدة أجهزة محلية.<\/p>", "group": "1-5", "lecture": "1", "href": "lesson.html#practice", "options": ["User Application", "Gateway / Edge", "Physical Actuator", "Device Memory"], "correct": 1, "explanation": "Gateway / Edge ممكن يجمع بيانات عدة أجهزة محلية.", "persist": "q1"}, {"id": "q-0b62aef8bde3c6", "type": "mcq", "prompt": "Which component is associated with boot and configuration?", "answerHTML": "<p>A. Device Software<\/p><p>Boot وConfiguration من وظائف Device Software.<\/p>", "group": "1-5", "lecture": "1", "href": "lesson.html#practice", "options": ["Device Software", "Cloud Storage", "Connectivity", "User Application"], "correct": 0, "explanation": "Boot وConfiguration من وظائف Device Software.", "persist": "q2"}, {"id": "q-bb188dc159f0d6", "type": "mcq", "prompt": "Which statement is correct about IoT security?", "answerHTML": "<p>C. The complete device-service ecosystem must be considered<\/p><p>لازم نأخذ النظام الكامل Device-Service Ecosystem بالحسبان.<\/p>", "group": "1-5", "lecture": "1", "href": "lesson.html#practice", "options": ["Only the physical device matters", "Only the network matters", "The complete device-service ecosystem must be considered", "Cloud services cannot affect device security"], "correct": 2, "explanation": "لازم نأخذ النظام الكامل Device-Service Ecosystem بالحسبان.", "persist": "q3"}, {"id": "q-c98f0768c855d0", "type": "short", "prompt": "Q1. Which component collects temperature readings?", "answerHTML": "<p><strong>Answer:<\/strong> Sensor.<\/p>", "group": "6", "lecture": "1", "href": "lesson.html#slide-6", "context": "A smart environmental sensor is installed in a public park. It collects temperature readings and stores configuration information locally."}, {"id": "q-f6424194de82f1", "type": "short", "prompt": "Q2. Which component may contain identifiers and configuration?", "answerHTML": "<p><strong>Answer:<\/strong> Local Memory / Storage.<\/p>", "group": "6", "lecture": "1", "href": "lesson.html#slide-6", "context": "A smart environmental sensor is installed in a public park. It collects temperature readings and stores configuration information locally."}, {"id": "q-86ff6e9a356db5", "type": "short", "prompt": "Q3. What security concern is introduced by its installation location?", "answerHTML": "<p><strong>Answer:<\/strong> Physical Exposure.<\/p><p><strong>الشرح:<\/strong> الجهاز موجود بمكان عام، فإمكانية الوصول الفيزيائي إله بتكون عامل لازم المهندس الأمني ياخذه بالحسبان.<\/p>", "group": "6", "lecture": "1", "href": "lesson.html#slide-6", "context": "A smart environmental sensor is installed in a public park. It collects temperature readings and stores configuration information locally."}, {"id": "q-0313f50007047f", "type": "short", "prompt": "Question: Which security consideration becomes important?", "answerHTML": "<p><strong>Correct Answer:<\/strong> Long-term software maintainability.<\/p><p><strong>الشرح:<\/strong> استمرار تشغيل الجهاز مش دليل كافي على إنه مناسب أمنيًا لكل الظروف الجديدة. لازم نفكر بقدرته على الصيانة والدعم.<\/p><p><strong>ملاحظة من المحاضرة:<\/strong> Firmware protection and detailed update mechanisms are reserved for later weeks. المطلوب هون تفهم أهمية برمجيات الجهاز، مش تفاصيل حمايتها.<\/p>", "group": "7", "lecture": "1", "href": "lesson.html#slide-7", "context": "An IoT device has been operating for eight years. Its embedded software still performs its basic functions, but the surrounding network and services have changed."}, {"id": "q-d9237c787b6121", "type": "short", "prompt": "Question: Why might its communication requirements differ from those of a video-streaming camera?", "answerHTML": "<p><strong>Correct Answer (English):<\/strong><\/p><p>IoT devices have different operational priorities. Some prioritize low power, range, or reliability rather than high bandwidth.<\/p><p><strong>الشرح:<\/strong> لأن طبيعة عمل الأجهزة مختلفة. الحساس الصغير ممكن تكون الطاقة عنده أهم من سرعة نقل البيانات، بينما جهاز آخر عنده احتياجات مختلفة.<\/p>", "group": "8", "lecture": "1", "href": "lesson.html#slide-8", "context": "A battery-powered IoT sensor prioritizes low energy consumption and reliable communication over high bandwidth."}, {"id": "q-88e33ce07800b0", "type": "short", "prompt": "Q1. Which component failed?", "answerHTML": "<p>Gateway / Edge.<\/p>", "group": "9", "lecture": "1", "href": "lesson.html#slide-9", "context": ""}, {"id": "q-e04fa8f4d8550e", "type": "short", "prompt": "Q2. Which security challenge is illustrated?", "answerHTML": "<p>Dependencies.<\/p>", "group": "9", "lecture": "1", "href": "lesson.html#slide-9", "context": ""}, {"id": "q-ec30a8ffbd19c8", "type": "short", "prompt": "Q3. Why is the gateway important?", "answerHTML": "<p>Because multiple devices depend on it for communication and management.<\/p>", "group": "9", "lecture": "1", "href": "lesson.html#slide-9", "context": ""}, {"id": "q-a0960e993ab0f3", "type": "short", "prompt": "Q4. Does gateway failure necessarily mean that every sensor stops sensing?", "answerHTML": "<p>No. Local sensing may continue if supported by the devices, while gateway-dependent communication becomes unavailable.<\/p><p><strong>الشرح:<\/strong> لازم نميز بين الوظيفة المحلية للجهاز وبين الخدمات اللي بتحتاج Gateway. مش كل عطل بالبوابة يعني إن الجهاز نفسه توقف بالكامل.<\/p>", "group": "9", "lecture": "1", "href": "lesson.html#slide-9", "context": ""}, {"id": "q-8d1994baf71238", "type": "short", "prompt": "Question: Why can a cloud-side failure affect a large population of devices?", "answerHTML": "<p><strong>Correct Answer:<\/strong><\/p><p>Because many IoT devices may depend on the same remote infrastructure for management and other services.<\/p><p><strong>الشرح:<\/strong> الأجهزة بتشترك بخدمة مركزية. لذلك تعطلها ممكن يكون تأثيره واسع، حتى لو الأجهزة الفيزيائية نفسها ما تعطلت.<\/p>", "group": "10", "lecture": "1", "href": "lesson.html#slide-10", "context": "A company manages 10,000 IoT devices using one cloud platform. A failure in the cloud service prevents administrators from remotely managing the devices."}, {"id": "q-a7d50f0e0bd959", "type": "short", "prompt": "Q1. Which ecosystem component enables users to control the lock?", "answerHTML": "<p>User Application.<\/p>", "group": "11", "lecture": "1", "href": "lesson.html#slide-11", "context": "A smart lock application allows users to share access with family members. An administrator can also manage the system."}, {"id": "q-acdfd120efa4dd", "type": "short", "prompt": "Q2. Which human workflow is relevant?", "answerHTML": "<p>Sharing and Permissions.<\/p>", "group": "11", "lecture": "1", "href": "lesson.html#slide-11", "context": "A smart lock application allows users to share access with family members. An administrator can also manage the system."}, {"id": "q-2886fe4da004a5", "type": "short", "prompt": "Q3. Why must human interaction be considered part of the system boundary?", "answerHTML": "<p>Because user and administrator actions can influence system access, configuration, and operation.<\/p><p><strong>الشرح:<\/strong> المشكلة الأمنية مش شرط تكون في جهاز القفل. ممكن تكون مرتبطة بطريقة استخدام التطبيق أو إدارة الوصول.<\/p>", "group": "11", "lecture": "1", "href": "lesson.html#slide-11", "context": "A smart lock application allows users to share access with family members. An administrator can also manage the system."}, {"id": "q-8881a96914ccc1", "type": "mcq", "prompt": "Which component executes device logic and handles communication with other components?", "answerHTML": "<p>B. Processor<\/p><p>Processor بينفذ منطق الجهاز وبتعامل مع الاتصال.<\/p>", "group": "6-11", "lecture": "1", "href": "lesson.html#practice-6-11", "options": ["Sensor", "Processor", "Actuator", "Cloud Service"], "correct": 1, "explanation": "Processor بينفذ منطق الجهاز وبتعامل مع الاتصال.", "persist": "lecture1-6-11-q1"}, {"id": "q-5e4429b7e12681", "type": "mcq", "prompt": "Which of the following may be stored in local device memory?", "answerHTML": "<p>C. Configuration, identifiers, and logs<\/p><p>الذاكرة المحلية ممكن تحتوي Configuration وIdentifiers وLogs.<\/p>", "group": "6-11", "lecture": "1", "href": "lesson.html#practice-6-11", "options": ["Only temperature readings", "Only video recordings", "Configuration, identifiers, and logs", "Only cloud account information"], "correct": 2, "explanation": "الذاكرة المحلية ممكن تحتوي Configuration وIdentifiers وLogs.", "persist": "lecture1-6-11-q2"}, {"id": "q-944964868dde05", "type": "mcq", "prompt": "Why is physical accessibility important in IoT security?", "answerHTML": "<p>B. Devices may be reachable outside protected environments<\/p><p>الجهاز ممكن يكون متاحًا خارج بيئة محمية.<\/p>", "group": "6-11", "lecture": "1", "href": "lesson.html#practice-6-11", "options": ["IoT devices never contain software", "Devices may be reachable outside protected environments", "Physical access always disables the device", "IoT devices cannot communicate remotely"], "correct": 1, "explanation": "الجهاز ممكن يكون متاحًا خارج بيئة محمية.", "persist": "lecture1-6-11-q3"}, {"id": "q-e4b2894b9a5937", "type": "mcq", "prompt": "Which function is controlled by embedded device software?", "answerHTML": "<p>A. Boot and configuration<\/p><p>Embedded Software بيتحكم في Boot وConfiguration.<\/p>", "group": "6-11", "lecture": "1", "href": "lesson.html#practice-6-11", "options": ["Boot and configuration", "Only physical sensing", "Only cloud storage", "Only the installation location"], "correct": 0, "explanation": "Embedded Software بيتحكم في Boot وConfiguration.", "persist": "lecture1-6-11-q4"}, {"id": "q-44884b2f875b08", "type": "mcq", "prompt": "Why does long-term software maintainability matter?", "answerHTML": "<p>C. The surrounding environment may change while software remains deployed<\/p><p>البيئة المحيطة ممكن تتغير بينما البرنامج يظل مستخدمًا.<\/p>", "group": "6-11", "lecture": "1", "href": "lesson.html#practice-6-11", "options": ["All IoT devices are replaced every year", "IoT software never changes", "The surrounding environment may change while software remains deployed", "All devices use the same operating system"], "correct": 2, "explanation": "البيئة المحيطة ممكن تتغير بينما البرنامج يظل مستخدمًا.", "persist": "lecture1-6-11-q5"}, {"id": "q-34ee6c27588a4c", "type": "mcq", "prompt": "Which statement about IoT connectivity is correct?", "answerHTML": "<p>D. Devices may communicate locally, through gateways, or through the Internet<\/p><p>الاتصال ممكن يكون محليًا أو عبر Gateway أو الإنترنت.<\/p>", "group": "6-11", "lecture": "1", "href": "lesson.html#practice-6-11", "options": ["All devices must connect directly to the Internet", "Wi-Fi is the only possible communication technology", "All IoT devices prioritize high bandwidth", "Devices may communicate locally, through gateways, or through the Internet"], "correct": 3, "explanation": "الاتصال ممكن يكون محليًا أو عبر Gateway أو الإنترنت.", "persist": "lecture1-6-11-q6"}, {"id": "q-2a78842e734ca1", "type": "mcq", "prompt": "Which component may aggregate data and translate communication?", "answerHTML": "<p>A. Gateway / Edge<\/p><p>Gateway ممكن يجمع البيانات ويكيّف الاتصال.<\/p>", "group": "6-11", "lecture": "1", "href": "lesson.html#practice-6-11", "options": ["Gateway / Edge", "Actuator", "User Application", "Sensor"], "correct": 0, "explanation": "Gateway ممكن يجمع البيانات ويكيّف الاتصال.", "persist": "lecture1-6-11-q7"}, {"id": "q-629c982a246c1b", "type": "mcq", "prompt": "Why can a gateway become an important trust point?", "answerHTML": "<p>B. Many devices may depend on one gateway<\/p><p>عدة أجهزة ممكن تعتمد على بوابة واحدة.<\/p>", "group": "6-11", "lecture": "1", "href": "lesson.html#practice-6-11", "options": ["It never communicates with remote services", "Many devices may depend on one gateway", "It eliminates the need for device software", "It always replaces cloud services"], "correct": 1, "explanation": "عدة أجهزة ممكن تعتمد على بوابة واحدة.", "persist": "lecture1-6-11-q8"}, {"id": "q-f8241521be3c2b", "type": "mcq", "prompt": "Which function is commonly associated with cloud services?", "answerHTML": "<p>C. Remote device registration and account management<\/p><p>Cloud Service بتدير تسجيل الأجهزة والحسابات عن بُعد.<\/p>", "group": "6-11", "lecture": "1", "href": "lesson.html#practice-6-11", "options": ["Physical temperature measurement", "Direct mechanical movement", "Remote device registration and account management", "Local sensor actuation only"], "correct": 2, "explanation": "Cloud Service بتدير تسجيل الأجهزة والحسابات عن بُعد.", "persist": "lecture1-6-11-q9"}, {"id": "q-420a9f733f2d23", "type": "mcq", "prompt": "Which statement about human interaction is correct?", "answerHTML": "<p>D. Human workflows such as sharing and recovery are part of the security boundary<\/p><p>Sharing وRecovery وغيرها من تفاعل البشر جزء من حدود النظام.<\/p>", "group": "6-11", "lecture": "1", "href": "lesson.html#practice-6-11", "options": ["Only administrators affect IoT security", "User experience has no security implications", "Installers are outside the system boundary", "Human workflows such as sharing and recovery are part of the security boundary"], "correct": 3, "explanation": "Sharing وRecovery وغيرها من تفاعل البشر جزء من حدود النظام.", "persist": "lecture1-6-11-q10"}, {"id": "q-2984e114091366", "type": "blank", "prompt": "Smart devices interact with the physical world through sensors and _______.", "answerHTML": "<p>actuators<\/p>", "group": "6-11", "lecture": "1", "href": "lesson.html#practice-6-11", "answer": "actuators"}, {"id": "q-99eb36601d8780", "type": "blank", "prompt": "The _______ executes device logic and handles communication.", "answerHTML": "<p>processor<\/p>", "group": "6-11", "lecture": "1", "href": "lesson.html#practice-6-11", "answer": "processor"}, {"id": "q-9278dd4dbb588e", "type": "blank", "prompt": "Local memory may contain configuration, identifiers, and _______.", "answerHTML": "<p>logs<\/p>", "group": "6-11", "lecture": "1", "href": "lesson.html#practice-6-11", "answer": "logs"}, {"id": "q-654062a85daabd", "type": "blank", "prompt": "Embedded software determines how the device starts, behaves, stores _______ and communicates.", "answerHTML": "<p>configuration<\/p>", "group": "6-11", "lecture": "1", "href": "lesson.html#practice-6-11", "answer": "configuration"}, {"id": "q-6d8352e4358aaf", "type": "blank", "prompt": "Some IoT devices prioritize low power, range, or _______ rather than high bandwidth.", "answerHTML": "<p>reliability<\/p>", "group": "6-11", "lecture": "1", "href": "lesson.html#practice-6-11", "answer": "reliability"}, {"id": "q-e682a42ee684dd", "type": "blank", "prompt": "A _______ can connect local devices to external networks and services.", "answerHTML": "<p>gateway<\/p>", "group": "6-11", "lecture": "1", "href": "lesson.html#practice-6-11", "answer": "gateway"}, {"id": "q-22ac6a9d12036f", "type": "blank", "prompt": "A gateway may aggregate data and translate _______.", "answerHTML": "<p>communication<\/p>", "group": "6-11", "lecture": "1", "href": "lesson.html#practice-6-11", "answer": "communication"}, {"id": "q-f918f3a9f6bec4", "type": "blank", "prompt": "Cloud services may store device data, manage accounts, and register _______.", "answerHTML": "<p>devices<\/p>", "group": "6-11", "lecture": "1", "href": "lesson.html#practice-6-11", "answer": "devices"}, {"id": "q-50670f19bce653", "type": "blank", "prompt": "A cloud-side failure may affect a large population of _______.", "answerHTML": "<p>devices<\/p>", "group": "6-11", "lecture": "1", "href": "lesson.html#practice-6-11", "answer": "devices"}, {"id": "q-3e67c6cbe8fd0d", "type": "blank", "prompt": "Human interaction is part of the system _______.", "answerHTML": "<p>boundary<\/p>", "group": "6-11", "lecture": "1", "href": "lesson.html#practice-6-11", "answer": "boundary"}, {"id": "q-9b8a58e36de1bf", "type": "short", "prompt": "Q1. Which devices are more typical of IoT?", "answerHTML": "<p><b>Answer:<\/b> The smart environmental sensors.<\/p>", "group": "12", "lecture": "1", "href": "lesson.html#slide-12", "context": "A company uses office laptops and 2,000 smart environmental sensors installed across several buildings. The sensors operate without continuous user interaction and have limited processing power."}, {"id": "q-42e3d345015fb1", "type": "short", "prompt": "Q2. Identify two differences between the sensors and traditional IT endpoints.", "answerHTML": "<p><b>Answer:<\/b> The sensors are often unattended and have resource and power constraints.<\/p>", "group": "12", "lecture": "1", "href": "lesson.html#slide-12", "context": "A company uses office laptops and 2,000 smart environmental sensors installed across several buildings. The sensors operate without continuous user interaction and have limited processing power."}, {"id": "q-358129c8ae7872", "type": "short", "prompt": "Q3. Which security challenge is introduced by deploying 2,000 sensors?", "answerHTML": "<p><b>Answer:<\/b> Scale.<\/p><p><b>التحليل<\/b><b> <\/b><b>بالعربي<\/b><b>:<\/b> انتبه لكلمات <i>2,000 sensors<\/i>، و<i>unattended<\/i>، و<i>limited processing power<\/i>. كل كلمة بتدل على مفهوم مختلف.<\/p>", "group": "12", "lecture": "1", "href": "lesson.html#slide-12", "context": "A company uses office laptops and 2,000 smart environmental sensors installed across several buildings. The sensors operate without continuous user interaction and have limited processing power."}, {"id": "q-36fc1938b51d8e", "type": "short", "prompt": "Question: Do all IoT devices require actuation capabilities?", "answerHTML": "<p><b>Answer:<\/b> No. Actuation is optional.<\/p><p>ليش؟ لأن التعريف استخدم كلمة <b>Sometimes<\/b>.<\/p>", "group": "13", "lecture": "1", "href": "lesson.html#slide-13", "context": ""}, {"id": "q-f63fdf43e39beb", "type": "short", "prompt": "Question: Which characteristic makes this system a Cyber-Physical System?", "answerHTML": "<p><b>Correct Answer:<\/b> Tight integration of computation with physical processes and feedback.<\/p><p><b>الشرح<\/b><b> <\/b><b>بالعربي<\/b><b>:<\/b> الكلمات المهمة هي <i>automatically adjusts<\/i> و<i>sensor feedback<\/i>. النظام مش بس بجمع بيانات، بل بستخدمها للتحكم بعملية فيزيائية.<\/p>", "group": "15", "lecture": "1", "href": "lesson.html#slide-15", "context": "A connected industrial system continuously measures temperature and automatically adjusts a cooling process based on sensor feedback."}, {"id": "q-e8feb2ae529e86", "type": "mcq", "prompt": "Which characteristic is more typical of IoT than Traditional IT?", "answerHTML": "<p>C. Often unattended operation<\/p><p>IoT كثيرًا ما يعمل بدون تفاعل بشري مستمر.<\/p>", "group": "12-17", "lecture": "1", "href": "lesson.html#practice-12-17", "options": ["Frequent user interaction", "General-purpose computing", "Often unattended operation", "Easy replacement"], "correct": 2, "explanation": "IoT كثيرًا ما يعمل بدون تفاعل بشري مستمر.", "persist": "lecture1-12-17-q1"}, {"id": "q-cfb2ad9d64baac", "type": "mcq", "prompt": "Which capability is optional in the lecture's definition of IoT?", "answerHTML": "<p>D. Actuation<\/p><p>التعريف بيقول Sometimes Actuation.<\/p>", "group": "12-17", "lecture": "1", "href": "lesson.html#practice-12-17", "options": ["Sensing", "Processing", "Communication", "Actuation"], "correct": 3, "explanation": "التعريف بيقول Sometimes Actuation.", "persist": "lecture1-12-17-q2"}, {"id": "q-6ed6aaecbe649c", "type": "mcq", "prompt": "What does CPS stand for?", "answerHTML": "<p>A. Cyber-Physical System<\/p><p>CPS اختصار Cyber-Physical System.<\/p>", "group": "12-17", "lecture": "1", "href": "lesson.html#practice-12-17", "options": ["Cyber-Physical System", "Cloud Processing Service", "Connected Physical Software", "Cyber Protection Standard"], "correct": 0, "explanation": "CPS اختصار Cyber-Physical System.", "persist": "lecture1-12-17-q3"}, {"id": "q-71103ca7d31efe", "type": "mcq", "prompt": "Which feature most clearly distinguishes a CPS in this lecture?", "answerHTML": "<p>B. Physical-process feedback<\/p><p>التمييز الأساسي هو Physical-process Feedback.<\/p>", "group": "12-17", "lecture": "1", "href": "lesson.html#practice-12-17", "options": ["Cloud storage", "Physical-process feedback", "Mobile application", "Large device count"], "correct": 1, "explanation": "التمييز الأساسي هو Physical-process Feedback.", "persist": "lecture1-12-17-q4"}, {"id": "q-13178c27a47f89", "type": "mcq", "prompt": "Which abbreviation refers to remote delivery of software or configuration?", "answerHTML": "<p>C. OTA<\/p><p>OTA يعني Over-the-Air.<\/p>", "group": "12-17", "lecture": "1", "href": "lesson.html#practice-12-17", "options": ["API", "UX", "OTA", "CPS"], "correct": 2, "explanation": "OTA يعني Over-the-Air.", "persist": "lecture1-12-17-q5"}, {"id": "q-86740ee4b08726", "type": "mcq", "prompt": "A battery-powered sensor has limited processing and memory. Which challenge is illustrated?", "answerHTML": "<p>B. Constraints<\/p><p>محدودية المعالجة والذاكرة والطاقة تعني Constraints.<\/p>", "group": "12-17", "lecture": "1", "href": "lesson.html#practice-12-17", "options": ["Scale", "Constraints", "Heterogeneity", "Dependencies"], "correct": 1, "explanation": "محدودية المعالجة والذاكرة والطاقة تعني Constraints.", "persist": "lecture1-12-17-q6"}, {"id": "q-7097cc89017e68", "type": "mcq", "prompt": "A sensor is installed in a publicly accessible location. Which challenge is most relevant?", "answerHTML": "<p>A. Physical Exposure<\/p><p>المكان المتاح للجمهور يعني Physical Exposure.<\/p>", "group": "12-17", "lecture": "1", "href": "lesson.html#practice-12-17", "options": ["Physical Exposure", "Scale", "Long Lifetime", "Heterogeneity"], "correct": 0, "explanation": "المكان المتاح للجمهور يعني Physical Exposure.", "persist": "lecture1-12-17-q7"}, {"id": "q-8dc91aef8cc721", "type": "mcq", "prompt": "One configuration error affects 20,000 deployed devices. This illustrates:", "answerHTML": "<p>C. Scale<\/p><p>الخطأ المتكرر على آلاف الأجهزة يعني Scale.<\/p>", "group": "12-17", "lecture": "1", "href": "lesson.html#practice-12-17", "options": ["UX", "CPS", "Scale", "OTA"], "correct": 2, "explanation": "الخطأ المتكرر على آلاف الأجهزة يعني Scale.", "persist": "lecture1-12-17-q8"}, {"id": "q-bd0f3d8ad426b1", "type": "mcq", "prompt": "Different manufacturers and communication technologies create which challenge?", "answerHTML": "<p>B. Heterogeneity<\/p><p>اختلاف الشركات والتقنيات يعني Heterogeneity.<\/p>", "group": "12-17", "lecture": "1", "href": "lesson.html#practice-12-17", "options": ["Physical Exposure", "Heterogeneity", "Constraints", "Actuation"], "correct": 1, "explanation": "اختلاف الشركات والتقنيات يعني Heterogeneity.", "persist": "lecture1-12-17-q9"}, {"id": "q-e1cb22966984cd", "type": "mcq", "prompt": "A device continues operating after its software support has ended. Which challenge is illustrated?", "answerHTML": "<p>D. Long Lifetime<\/p><p>استمرار الجهاز بعد انتهاء الدعم يعني Long Lifetime.<\/p>", "group": "12-17", "lecture": "1", "href": "lesson.html#practice-12-17", "options": ["Scale", "Physical Exposure", "Connectivity", "Long Lifetime"], "correct": 3, "explanation": "استمرار الجهاز بعد انتهاء الدعم يعني Long Lifetime.", "persist": "lecture1-12-17-q10"}, {"id": "q-0979f7932f33e3", "type": "mcq", "prompt": "A cloud failure prevents remote management of several smart devices. Which challenge is illustrated?", "answerHTML": "<p>A. Dependencies<\/p><p>تعطل خدمة يحتاجها الجهاز يعني Dependencies.<\/p>", "group": "12-17", "lecture": "1", "href": "lesson.html#practice-12-17", "options": ["Dependencies", "Heterogeneity", "Physical Exposure", "Constraints"], "correct": 0, "explanation": "تعطل خدمة يحتاجها الجهاز يعني Dependencies.", "persist": "lecture1-12-17-q11"}, {"id": "q-118005ab8a2c65", "type": "mcq", "prompt": "Which statement best describes the security unit of an IoT product?", "answerHTML": "<p>C. The complete device-service ecosystem<\/p><p>وحدة التحليل تشمل Complete Device-Service Ecosystem.<\/p>", "group": "12-17", "lecture": "1", "href": "lesson.html#practice-12-17", "options": ["Only the physical hardware", "Only the network connection", "The complete device-service ecosystem", "Only the cloud platform"], "correct": 2, "explanation": "وحدة التحليل تشمل Complete Device-Service Ecosystem.", "persist": "lecture1-12-17-q12"}, {"id": "q-a7c3efbcf0a83e", "type": "blank", "prompt": "IoT devices are often _______ rather than general-purpose computers.", "answerHTML": "<p>special-purpose<\/p>", "group": "12-17", "lecture": "1", "href": "lesson.html#practice-12-17", "answer": "special-purpose"}, {"id": "q-bbe3dce970e2ab", "type": "blank", "prompt": "IoT devices are often _______ without frequent user interaction.", "answerHTML": "<p>unattended<\/p>", "group": "12-17", "lecture": "1", "href": "lesson.html#practice-12-17", "answer": "unattended"}, {"id": "q-74e21e5b8c5d81", "type": "blank", "prompt": "The Internet of Things includes sensing, processing, communication, and sometimes _______.", "answerHTML": "<p>actuation<\/p>", "group": "12-17", "lecture": "1", "href": "lesson.html#practice-12-17", "answer": "actuation"}, {"id": "q-19f2f00f036386", "type": "blank", "prompt": "CPS stands for _______.", "answerHTML": "<p>Cyber-Physical System<\/p>", "group": "12-17", "lecture": "1", "href": "lesson.html#practice-12-17", "answer": "Cyber-Physical System"}, {"id": "q-b38070c617225f", "type": "blank", "prompt": "API stands for _______.", "answerHTML": "<p>Application Programming Interface<\/p>", "group": "12-17", "lecture": "1", "href": "lesson.html#practice-12-17", "answer": "Application Programming Interface"}, {"id": "q-1c089587aa81c5", "type": "blank", "prompt": "OTA stands for _______.", "answerHTML": "<p>Over-the-Air<\/p>", "group": "12-17", "lecture": "1", "href": "lesson.html#practice-12-17", "answer": "Over-the-Air"}, {"id": "q-a26d28131d2051", "type": "blank", "prompt": "UX stands for _______.", "answerHTML": "<p>User Experience<\/p>", "group": "12-17", "lecture": "1", "href": "lesson.html#practice-12-17", "answer": "User Experience"}, {"id": "q-e9537d3b602c3d", "type": "blank", "prompt": "Limited memory, processing, and power are examples of resource _______.", "answerHTML": "<p>constraints<\/p>", "group": "12-17", "lecture": "1", "href": "lesson.html#practice-12-17", "answer": "constraints"}, {"id": "q-64c7ab1a68d9de", "type": "blank", "prompt": "A configuration mistake repeated across thousands of devices illustrates _______.", "answerHTML": "<p>scale<\/p>", "group": "12-17", "lecture": "1", "href": "lesson.html#practice-12-17", "answer": "scale"}, {"id": "q-09bbd1e0504e8d", "type": "blank", "prompt": "Different vendors and communication technologies create _______.", "answerHTML": "<p>heterogeneity<\/p>", "group": "12-17", "lecture": "1", "href": "lesson.html#practice-12-17", "answer": "heterogeneity"}, {"id": "q-0235563690b03a", "type": "blank", "prompt": "Devices may outlive their software _______.", "answerHTML": "<p>support<\/p>", "group": "12-17", "lecture": "1", "href": "lesson.html#practice-12-17", "answer": "support"}, {"id": "q-7c272a1735f63d", "type": "blank", "prompt": "IoT devices may depend on gateways, networks, cloud services, and _______.", "answerHTML": "<p>applications<\/p>", "group": "12-17", "lecture": "1", "href": "lesson.html#practice-12-17", "answer": "applications"}, {"id": "q-9547d33c78a717", "type": "short", "prompt": "Q1. What physical service does the device support?", "answerHTML": "<p>Answer: Patient monitoring.<\/p>", "group": "18", "lecture": "1", "href": "lesson.html#slide-18", "context": "A hospital uses a connected medical sensor to monitor patient measurements. The sensor sends data to a cloud service used by clinical staff."}, {"id": "q-510944cdaad963", "type": "short", "prompt": "Q2. What data does the system collect?", "answerHTML": "<p>Answer: Patient measurements.<\/p>", "group": "18", "lecture": "1", "href": "lesson.html#slide-18", "context": "A hospital uses a connected medical sensor to monitor patient measurements. The sensor sends data to a cloud service used by clinical staff."}, {"id": "q-8547374c9cb1e1", "type": "short", "prompt": "Q3. What happens if the measurements are incorrect?", "answerHTML": "<p>Answer: Clinical staff may receive incorrect information, which could affect decisions based on those measurements.<\/p><p>التحليل بالعربي: لاحظ إننا حللنا وظيفة الجهاز والبيانات والاعتماد ونتائج الخطأ، بدون ما نحتاج نذكر أي هجوم محدد.<\/p>", "group": "18", "lecture": "1", "href": "lesson.html#slide-18", "context": "A hospital uses a connected medical sensor to monitor patient measurements. The sensor sends data to a cloud service used by clinical staff."}, {"id": "q-11dffeedb8418d", "type": "short", "prompt": "Q1. Identify four ecosystem elements.", "answerHTML": "<p>Answer: Physical Smart Lock, Mobile Application, Network Connection, Remote Service.<\/p>", "group": "19", "lecture": "1", "href": "lesson.html#slide-19", "context": "A smart door lock is controlled through a mobile application connected to a remote service. The owner and an installer both interact with the system."}, {"id": "q-c2ff05dc224e0c", "type": "short", "prompt": "Q2. Identify two human roles.", "answerHTML": "<p>Answer: Owner and Installer.<\/p>", "group": "19", "lecture": "1", "href": "lesson.html#slide-19", "context": "A smart door lock is controlled through a mobile application connected to a remote service. The owner and an installer both interact with the system."}, {"id": "q-b5c5673424aa09", "type": "short", "prompt": "Q3. What should be marked on the diagram?", "answerHTML": "<p>Answer: Information and command paths between components.<\/p>", "group": "19", "lecture": "1", "href": "lesson.html#slide-19", "context": "A smart door lock is controlled through a mobile application connected to a remote service. The owner and an installer both interact with the system."}, {"id": "q-5d953e0147a8c6", "type": "short", "prompt": "Why is the security boundary of a smart camera larger than the camera itself?", "answerHTML": "<p>Model Answer: Because the camera depends on software, network connections, remote services, applications, and human interaction.<\/p><p>الشرح: لأن المشكلة ممكن تكون في أي جزء من النظام، مش بس في الكاميرا نفسها.<\/p>", "group": "21", "lecture": "1", "href": "lesson.html#slide-21", "context": ""}, {"id": "q-d12c5ac1583712", "type": "short", "prompt": "Give two differences between traditional IT endpoints and IoT devices.", "answerHTML": "<p>Model Answer: Traditional IT endpoints are generally general-purpose and frequently used by people, while IoT devices are often special-purpose and unattended.<\/p><p>الشرح: الكمبيوتر متعدد الاستخدامات وغالبًا المستخدم بتفاعل معه، بينما كثير أجهزة IoT إلها وظيفة محددة وبتشتغل بدون متابعة مستمرة.<\/p>", "group": "21", "lecture": "1", "href": "lesson.html#slide-21", "context": ""}, {"id": "q-66dd42612f5976", "type": "short", "prompt": "Why can physical access matter more in IoT deployments?", "answerHTML": "<p>Model Answer: Because IoT devices may be installed in physically accessible locations where assumptions used for protected servers do not hold.<\/p><p>الشرح: لأن الجهاز ممكن يكون بمكان عام أو غير محمي مثل غرفة السيرفرات.<\/p>", "group": "21", "lecture": "1", "href": "lesson.html#slide-21", "context": ""}, {"id": "q-8ffea3b923e41c", "type": "short", "prompt": "What is the difference between IoT and a Cyber-Physical System at a high level?", "answerHTML": "<p>Model Answer: IoT focuses on connected physical objects and services, while CPS emphasizes tight interaction between computation and physical processes with feedback.<\/p><p>الشرح: IoT بيركز على الأجهزة المتصلة والخدمات، بينما CPS بيركز على العلاقة المباشرة بين الحوسبة والتحكم الفيزيائي والتغذية الراجعة.<\/p>", "group": "21", "lecture": "1", "href": "lesson.html#slide-21", "context": ""}, {"id": "q-1b73d9cf463989", "type": "short", "prompt": "Why should security engineers consider the complete device lifecycle?", "answerHTML": "<p>Model Answer: Because devices may remain deployed for years while software, services, networks, dependencies, and ownership change.<\/p><p>الشرح: لأنه الظروف اللي كان الجهاز شغال فيها وقت تركيبه ممكن تتغير مع مرور السنوات.<\/p>", "group": "21", "lecture": "1", "href": "lesson.html#slide-21", "context": ""}, {"id": "q-0db82496637d01", "type": "short", "prompt": "Q1. Which IoT category best describes this system?", "answerHTML": "<p>Answer: Industrial / Infrastructure IoT.<\/p>", "group": "22", "lecture": "1", "href": "lesson.html#slide-22", "context": "A factory uses connected sensors to monitor an industrial process. Incorrect sensor operation could affect production."}, {"id": "q-8656a86e90a699", "type": "short", "prompt": "Q2. Which phrase is the strongest clue?", "answerHTML": "<p>Answer: Operational consequences.<\/p><p>الشرح: مجرد وجود Sensors مش كافي لتحديد الفئة؛ لازم تشوف وين مستخدمة الأجهزة وشو نتائج فشلها.<\/p>", "group": "22", "lecture": "1", "href": "lesson.html#slide-22", "context": "A factory uses connected sensors to monitor an industrial process. Incorrect sensor operation could affect production."}, {"id": "q-0eda39711280e4", "type": "short", "prompt": "Q1. Who is responsible for embedded software decisions?", "answerHTML": "<p>Answer: Device Manufacturer.<\/p>", "group": "23", "lecture": "1", "href": "lesson.html#slide-23", "context": "A company installs smart cameras in an office. The manufacturer develops the device software, a cloud provider manages user accounts, an installer configures the cameras, and employees use the application daily."}, {"id": "q-783a1785202d62", "type": "short", "prompt": "Q2. Who manages account-related backend functions?", "answerHTML": "<p>Answer: Service Provider.<\/p>", "group": "23", "lecture": "1", "href": "lesson.html#slide-23", "context": "A company installs smart cameras in an office. The manufacturer develops the device software, a cloud provider manages user accounts, an installer configures the cameras, and employees use the application daily."}, {"id": "q-c9effcf359ac2e", "type": "short", "prompt": "Q3. Who is responsible for installation and network configuration?", "answerHTML": "<p>Answer: Installer / Organization.<\/p>", "group": "23", "lecture": "1", "href": "lesson.html#slide-23", "context": "A company installs smart cameras in an office. The manufacturer develops the device software, a cloud provider manages user accounts, an installer configures the cameras, and employees use the application daily."}, {"id": "q-0690631267d948", "type": "short", "prompt": "Q4. Who handles daily use and reports abnormal behavior?", "answerHTML": "<p>Answer: User / Operator.<\/p>", "group": "23", "lecture": "1", "href": "lesson.html#slide-23", "context": "A company installs smart cameras in an office. The manufacturer develops the device software, a cloud provider manages user accounts, an installer configures the cameras, and employees use the application daily."}, {"id": "q-67d04e444486b0", "type": "short", "prompt": "Q5. What security problem can arise if these responsibilities are unclear?", "answerHTML": "<p>Answer: Security gaps may appear between the responsible parties.<\/p>", "group": "23", "lecture": "1", "href": "lesson.html#slide-23", "context": "A company installs smart cameras in an office. The manufacturer develops the device software, a cloud provider manages user accounts, an installer configures the cameras, and employees use the application daily."}, {"id": "q-17239400364319", "type": "mcq", "prompt": "What should a security engineer do before looking for specific IoT vulnerabilities?", "answerHTML": "<p>B. Understand the device, its purpose, data, users, dependencies, and failure consequences<\/p><p>أول خطوة نفهم النظام ووظيفته ومكوناته والبيانات والأشخاص والاعتماد ونتائج الفشل.<\/p>", "group": "18-23", "lecture": "1", "href": "lesson.html#practice-18-23", "options": ["Immediately identify attacks", "Understand the device, its purpose, data, users, dependencies, and failure consequences", "Ignore the physical environment", "Analyze only the cloud service"], "correct": 1, "explanation": "أول خطوة نفهم النظام ووظيفته ومكوناته والبيانات والأشخاص والاعتماد ونتائج الفشل.", "persist": "lecture1-18-23-q1"}, {"id": "q-b9ad87c9b14967", "type": "mcq", "prompt": "Which question helps identify the information handled by an IoT system?", "answerHTML": "<p>C. What data does the system collect, store, or transmit?<\/p><p>Collect, Store, Transmit هي الكلمات الأساسية لفهم البيانات اللي بتتعامل معها المنظومة.<\/p>", "group": "18-23", "lecture": "1", "href": "lesson.html#practice-18-23", "options": ["Who manufactured the device?", "Where is the company located?", "What data does the system collect, store, or transmit?", "How many computers are in the office?"], "correct": 2, "explanation": "Collect, Store, Transmit هي الكلمات الأساسية لفهم البيانات اللي بتتعامل معها المنظومة.", "persist": "lecture1-18-23-q2"}, {"id": "q-ddfd118e90521c", "type": "mcq", "prompt": "In a smart lock mapping activity, what should be identified first?", "answerHTML": "<p>A. The device, application, network connection, and remote service<\/p><p>النشاط بطلب تحديد مكونات النظام ومسارات المعلومات والأوامر قبل تحليل الهجمات.<\/p>", "group": "18-23", "lecture": "1", "href": "lesson.html#practice-18-23", "options": ["The device, application, network connection, and remote service", "Only the attacker's location", "Only known vulnerabilities", "Only encryption methods"], "correct": 0, "explanation": "النشاط بطلب تحديد مكونات النظام ومسارات المعلومات والأوامر قبل تحليل الهجمات.", "persist": "lecture1-18-23-q3"}, {"id": "q-cb383b4f94c828", "type": "mcq", "prompt": "Why is treating IoT as a small traditional computer a mistake?", "answerHTML": "<p>D. IoT may have limited resources, unusual hardware, physical effects, and external dependencies<\/p><p>أجهزة IoT إلها خصائص بتخلي التحليل الأمني مختلف عن الافتراضات التقليدية.<\/p>", "group": "18-23", "lecture": "1", "href": "lesson.html#practice-18-23", "options": ["IoT devices never contain processors", "IoT devices cannot communicate", "Traditional computers have no software", "IoT may have limited resources, unusual hardware, physical effects, and external dependencies"], "correct": 3, "explanation": "أجهزة IoT إلها خصائص بتخلي التحليل الأمني مختلف عن الافتراضات التقليدية.", "persist": "lecture1-18-23-q4"}, {"id": "q-cf48bbc4e65e8f", "type": "mcq", "prompt": "Which category includes smart cameras, speakers, and wearables used by individuals?", "answerHTML": "<p>B. Consumer IoT<\/p><p>Consumer IoT غالبًا بستخدمه أشخاص عاديون وغير متخصصين.<\/p>", "group": "18-23", "lecture": "1", "href": "lesson.html#practice-18-23", "options": ["Industrial IoT", "Consumer IoT", "Enterprise IoT", "Infrastructure IoT"], "correct": 1, "explanation": "Consumer IoT غالبًا بستخدمه أشخاص عاديون وغير متخصصين.", "persist": "lecture1-18-23-q5"}, {"id": "q-b71ad548fd85af", "type": "mcq", "prompt": "Which IoT category is commonly managed at a larger organizational scale?", "answerHTML": "<p>C. Enterprise / Building IoT<\/p><p>Enterprise / Building IoT يشمل أنظمة المباني والتحكم بالدخول والحساسات المُدارة على نطاق أكبر.<\/p>", "group": "18-23", "lecture": "1", "href": "lesson.html#practice-18-23", "options": ["Consumer IoT", "Personal IoT", "Enterprise / Building IoT", "Offline computing"], "correct": 2, "explanation": "Enterprise / Building IoT يشمل أنظمة المباني والتحكم بالدخول والحساسات المُدارة على نطاق أكبر.", "persist": "lecture1-18-23-q6"}, {"id": "q-a553082ef1ebae", "type": "mcq", "prompt": "Which category may involve significant operational consequences from incorrect operation?", "answerHTML": "<p>A. Industrial / Infrastructure IoT<\/p><p>الأنظمة الصناعية والبنية التحتية ممكن يكون لأخطاء تشغيلها نتائج عملية مهمة.<\/p>", "group": "18-23", "lecture": "1", "href": "lesson.html#practice-18-23", "options": ["Industrial / Infrastructure IoT", "Consumer IoT only", "Personal entertainment devices only", "Traditional desktop systems only"], "correct": 0, "explanation": "الأنظمة الصناعية والبنية التحتية ممكن يكون لأخطاء تشغيلها نتائج عملية مهمة.", "persist": "lecture1-18-23-q7"}, {"id": "q-62c062fe2790ee", "type": "mcq", "prompt": "Who is responsible for hardware and embedded software decisions?", "answerHTML": "<p>D. Device Manufacturer<\/p><p>الشركة المصنعة مسؤولة عن القرارات المتعلقة بمكونات الجهاز والبرمجيات المدمجة.<\/p>", "group": "18-23", "lecture": "1", "href": "lesson.html#practice-18-23", "options": ["User / Operator", "Installer", "Service Provider", "Device Manufacturer"], "correct": 3, "explanation": "الشركة المصنعة مسؤولة عن القرارات المتعلقة بمكونات الجهاز والبرمجيات المدمجة.", "persist": "lecture1-18-23-q8"}, {"id": "q-1a7bce8d869ed4", "type": "mcq", "prompt": "Who is most directly responsible for network placement and initial configuration?", "answerHTML": "<p>B. Installer / Organization<\/p><p>التركيب ومكان الجهاز على الشبكة والإعدادات من مسؤولية Installer / Organization.<\/p>", "group": "18-23", "lecture": "1", "href": "lesson.html#practice-18-23", "options": ["Device Manufacturer", "Installer / Organization", "End User only", "Cloud Storage Provider"], "correct": 1, "explanation": "التركيب ومكان الجهاز على الشبكة والإعدادات من مسؤولية Installer / Organization.", "persist": "lecture1-18-23-q9"}, {"id": "q-ff3ef50a0541b0", "type": "mcq", "prompt": "Which party handles backend and remote account-related responsibilities?", "answerHTML": "<p>C. Service Provider<\/p><p>Service Provider مسؤول عن Backend والإدارة عن بُعد والحسابات.<\/p>", "group": "18-23", "lecture": "1", "href": "lesson.html#practice-18-23", "options": ["Device Manufacturer", "Installer", "Service Provider", "Physical Sensor"], "correct": 2, "explanation": "Service Provider مسؤول عن Backend والإدارة عن بُعد والحسابات.", "persist": "lecture1-18-23-q10"}, {"id": "q-0d6a729229e33b", "type": "mcq", "prompt": "Which activity is associated with the User / Operator?", "answerHTML": "<p>A. Reporting abnormal behavior<\/p><p>المستخدم مسؤول عن الاستخدام اليومي والتعامل مع الحساب والإبلاغ عن السلوك غير الطبيعي.<\/p>", "group": "18-23", "lecture": "1", "href": "lesson.html#practice-18-23", "options": ["Reporting abnormal behavior", "Designing device hardware", "Manufacturing processors", "Developing all embedded software"], "correct": 0, "explanation": "المستخدم مسؤول عن الاستخدام اليومي والتعامل مع الحساب والإبلاغ عن السلوك غير الطبيعي.", "persist": "lecture1-18-23-q11"}, {"id": "q-7bbb5a1ceee8ee", "type": "mcq", "prompt": "Security gaps may appear when:", "answerHTML": "<p>D. Responsibilities between different parties are unclear<\/p><p>عدم وضوح المسؤوليات بين الأطراف ممكن يخلق فجوات أمنية.<\/p>", "group": "18-23", "lecture": "1", "href": "lesson.html#practice-18-23", "options": ["Every device has a sensor", "A system includes a mobile application", "Devices operate locally", "Responsibilities between different parties are unclear"], "correct": 3, "explanation": "عدم وضوح المسؤوليات بين الأطراف ممكن يخلق فجوات أمنية.", "persist": "lecture1-18-23-q12"}, {"id": "q-db62827d2c268f", "type": "blank", "prompt": "Before looking for vulnerabilities, engineers should understand the device's physical process or _______.", "answerHTML": "<p>service<\/p>", "group": "18-23", "lecture": "1", "href": "lesson.html#practice-18-23", "answer": "service"}, {"id": "q-c5a1b5b2380cb3", "type": "blank", "prompt": "Security engineers should identify what data a system collects, stores, or _______.", "answerHTML": "<p>transmits<\/p>", "group": "18-23", "lecture": "1", "href": "lesson.html#practice-18-23", "answer": "transmits"}, {"id": "q-6d4855f0597048", "type": "blank", "prompt": "A device may depend on gateways, networks, cloud services, and other _______.", "answerHTML": "<p>systems<\/p>", "group": "18-23", "lecture": "1", "href": "lesson.html#practice-18-23", "answer": "systems"}, {"id": "q-1fdf6a7b3a25af", "type": "blank", "prompt": "A smart lock mapping activity should mark where information or _______ move between components.", "answerHTML": "<p>commands<\/p>", "group": "18-23", "lecture": "1", "href": "lesson.html#practice-18-23", "answer": "commands"}, {"id": "q-f2bbad448b090d", "type": "blank", "prompt": "IoT devices may have limited resources, unusual hardware, and long deployment _______.", "answerHTML": "<p>periods<\/p>", "group": "18-23", "lecture": "1", "href": "lesson.html#practice-18-23", "answer": "periods"}, {"id": "q-87453488156077", "type": "blank", "prompt": "Consumer IoT devices are often deployed by _______ users.", "answerHTML": "<p>non-specialist<\/p>", "group": "18-23", "lecture": "1", "href": "lesson.html#practice-18-23", "answer": "non-specialist"}, {"id": "q-b905fd272dd357", "type": "blank", "prompt": "Access control and smart building systems are examples of _______ IoT.", "answerHTML": "<p>Enterprise / Building<\/p>", "group": "18-23", "lecture": "1", "href": "lesson.html#practice-18-23", "answer": "Enterprise / Building"}, {"id": "q-1f3e253478ad5a", "type": "blank", "prompt": "Industrial devices may have important _______ consequences when operating incorrectly.", "answerHTML": "<p>operational<\/p>", "group": "18-23", "lecture": "1", "href": "lesson.html#practice-18-23", "answer": "operational"}, {"id": "q-21e4a4eb4b2df5", "type": "blank", "prompt": "The device _______ is responsible for hardware and embedded software decisions.", "answerHTML": "<p>manufacturer<\/p>", "group": "18-23", "lecture": "1", "href": "lesson.html#practice-18-23", "answer": "manufacturer"}, {"id": "q-bec93ea45eb9bb", "type": "blank", "prompt": "The service provider handles backend and remote _______.", "answerHTML": "<p>management<\/p>", "group": "18-23", "lecture": "1", "href": "lesson.html#practice-18-23", "answer": "management"}, {"id": "q-950bff5e640976", "type": "blank", "prompt": "The installer or organization is responsible for deployment, network placement, and _______.", "answerHTML": "<p>configuration<\/p>", "group": "18-23", "lecture": "1", "href": "lesson.html#practice-18-23", "answer": "configuration"}, {"id": "q-4e39dfbe35a867", "type": "blank", "prompt": "Security gaps often appear when responsibility between parties is _______.", "answerHTML": "<p>unclear<\/p>", "group": "18-23", "lecture": "1", "href": "lesson.html#practice-18-23", "answer": "unclear"}, {"id": "q-a45aef5ab12b68", "type": "short", "prompt": "Q1. Identify the telemetry path.", "answerHTML": "<p>Answer: Thermostat → Cloud Service → Dashboard.<\/p>", "group": "24", "lecture": "1", "href": "lesson.html#slide-24", "context": "A smart thermostat sends temperature readings to a cloud dashboard. A user can also send commands through a mobile application to adjust the heating system."}, {"id": "q-f4aa0e7631390f", "type": "short", "prompt": "Q2. Identify the control path.", "answerHTML": "<p>Answer: Mobile Application → Cloud Service → Thermostat / Heating Control.<\/p>", "group": "24", "lecture": "1", "href": "lesson.html#slide-24", "context": "A smart thermostat sends temperature readings to a cloud dashboard. A user can also send commands through a mobile application to adjust the heating system."}, {"id": "q-7f241076bd6ed3", "type": "short", "prompt": "Q3. Why is the control path security-relevant?", "answerHTML": "<p>Answer: Because control commands can influence physical device behavior.<\/p>", "group": "24", "lecture": "1", "href": "lesson.html#slide-24", "context": "A smart thermostat sends temperature readings to a cloud dashboard. A user can also send commands through a mobile application to adjust the heating system."}, {"id": "q-977c118e0e7987", "type": "short", "prompt": "Q1. Identify the physical layer.", "answerHTML": "<p>Answer: Door sensors, cameras, and access-control devices.<\/p>", "group": "25", "lecture": "1", "href": "lesson.html#slide-25", "context": "A building contains door sensors, security cameras, and access-control devices. Local gateways collect device information and send it to a remote management dashboard."}, {"id": "q-afd68389077fc2", "type": "short", "prompt": "Q2. Identify the local layer.", "answerHTML": "<p>Answer: Gateways.<\/p>", "group": "25", "lecture": "1", "href": "lesson.html#slide-25", "context": "A building contains door sensors, security cameras, and access-control devices. Local gateways collect device information and send it to a remote management dashboard."}, {"id": "q-dd2382021c4850", "type": "short", "prompt": "Q3. Identify the remote layer.", "answerHTML": "<p>Answer: Remote Management Dashboard / Service.<\/p>", "group": "25", "lecture": "1", "href": "lesson.html#slide-25", "context": "A building contains door sensors, security cameras, and access-control devices. Local gateways collect device information and send it to a remote management dashboard."}, {"id": "q-0a4b52f48d21dd", "type": "short", "prompt": "Q4. Why is analyzing only the physical devices insufficient?", "answerHTML": "<p>Answer: Because the devices depend on local communication, gateways, remote services, and human interaction.<\/p>", "group": "25", "lecture": "1", "href": "lesson.html#slide-25", "context": "A building contains door sensors, security cameras, and access-control devices. Local gateways collect device information and send it to a remote management dashboard."}, {"id": "q-82e4f4c71e9688", "type": "short", "prompt": "Q1. Which security challenge is illustrated?", "answerHTML": "<p>Answer: Scale.<\/p>", "group": "26", "lecture": "1", "href": "lesson.html#slide-26", "context": "A company deploys 8,000 identical smart sensors across multiple locations. A configuration error is present in every sensor."}, {"id": "q-7e71279da7f96f", "type": "short", "prompt": "Q2. Why is the error more significant than a similar error on one laptop?", "answerHTML": "<p>Answer: Because the same mistake is reproduced across an entire fleet.<\/p>", "group": "26", "lecture": "1", "href": "lesson.html#slide-26", "context": "A company deploys 8,000 identical smart sensors across multiple locations. A configuration error is present in every sensor."}, {"id": "q-015f83c5364e24", "type": "short", "prompt": "Q3. Name four important management processes.", "answerHTML": "<p>Answer: Onboarding, Inventory, Maintenance, and Retirement.<\/p>", "group": "26", "lecture": "1", "href": "lesson.html#slide-26", "context": "A company deploys 8,000 identical smart sensors across multiple locations. A configuration error is present in every sensor."}, {"id": "q-36c954985308f1", "type": "short", "prompt": "Q4. Why is direct inspection difficult?", "answerHTML": "<p>Answer: Because devices may be distributed across many locations.<\/p>", "group": "26", "lecture": "1", "href": "lesson.html#slide-26", "context": "A company deploys 8,000 identical smart sensors across multiple locations. A configuration error is present in every sensor."}, {"id": "q-63cc4964178c21", "type": "short", "prompt": "Q1. Which security challenge is illustrated?", "answerHTML": "<p>Answer: Long Lifetime.<\/p>", "group": "27", "lecture": "1", "href": "lesson.html#slide-27", "context": "A smart meter has been installed for 12 years. It still collects readings, but some of its software dependencies are no longer supported."}, {"id": "q-628d7a05e25927", "type": "short", "prompt": "Q2. What may become outdated?", "answerHTML": "<p>Answer: Security assumptions and software dependencies.<\/p>", "group": "27", "lecture": "1", "href": "lesson.html#slide-27", "context": "A smart meter has been installed for 12 years. It still collects readings, but some of its software dependencies are no longer supported."}, {"id": "q-0e3a346278954a", "type": "short", "prompt": "Q3. What should the organization know?", "answerHTML": "<p>Answer: Which devices exist and whether they remain supportable.<\/p><p>ملاحظة: السلايد بتذكر إن تفاصيل تحديث الأجهزة وحماية دورة حياتها رح تنشرح في Week 6، فهون ركز على المفهوم الأساسي.<\/p>", "group": "27", "lecture": "1", "href": "lesson.html#slide-27", "context": "A smart meter has been installed for 12 years. It still collects readings, but some of its software dependencies are no longer supported."}, {"id": "q-d16ab094d58335", "type": "short", "prompt": "Question 1 — List the ecosystem components without discussing specific attacks.", "answerHTML": "<p>Model Answer (English): The ecosystem includes the patient sensor, embedded device software, communication network, remote service, clinical application, and clinical staff. A gateway may also be present depending on the architecture.<\/p><p>الشرح بالعربي: بنبدأ بالحساس نفسه، بعدين برمجياته، والاتصال، والخدمة، والتطبيق، والأشخاص. لاحظ إن Gateway مش مذكور صراحة في السيناريو، لذلك ما بنقدر نفترض إنه موجود أكيد.<\/p>", "group": "28", "lecture": "1", "href": "lesson.html#slide-28", "context": "A patient sensor collects measurements and sends them to a service used by clinical staff."}, {"id": "q-5ba3498db3b10c", "type": "short", "prompt": "Question 2 — Which components are physically accessible? Which are remotely managed?", "answerHTML": "<p>Model Answer (English): The patient sensor is physically accessible in the clinical environment. The remote service and its management functions may be administered remotely.<\/p><p>الشرح بالعربي: الحساس نفسه موجود في البيئة الطبية وممكن الوصول إله فيزيائيًا. أما الخدمة البعيدة، فإدارتها ممكن تكون عن بُعد.<\/p>", "group": "28", "lecture": "1", "href": "lesson.html#slide-28", "context": "A patient sensor collects measurements and sends them to a service used by clinical staff."}, {"id": "q-d2598432a17807", "type": "short", "prompt": "Question 3 — What would matter more: Data Exposure, Incorrect Data, Service Interruption, or Incorrect Physical Behavior?", "answerHTML": "<p>هاي أهم نقطة في السيناريو، ولازم نفهم الخيارات الأربعة:<\/p>", "group": "28", "lecture": "1", "href": "lesson.html#slide-28", "context": "A patient sensor collects measurements and sends them to a service used by clinical staff."}, {"id": "q-846bf4cb818988", "type": "mcq", "prompt": "Which term describes measurements flowing from physical devices toward applications?", "answerHTML": "<p>B. Telemetry<\/p><p>Telemetry هي البيانات والقياسات اللي بتنتقل من الجهاز باتجاه التطبيقات والخدمات.<\/p>", "group": "24-29", "lecture": "1", "href": "lesson.html#practice-24-29", "options": ["Actuation", "Telemetry", "Control Command", "Onboarding"], "correct": 1, "explanation": "Telemetry هي البيانات والقياسات اللي بتنتقل من الجهاز باتجاه التطبيقات والخدمات.", "persist": "lecture1-24-29-q1"}, {"id": "q-c9864ad107161e", "type": "mcq", "prompt": "Which action best represents a control path?", "answerHTML": "<p>C. An application sends an unlock command<\/p><p>أمر الفتح بيؤثر على سلوك الجهاز الفيزيائي، لذلك هو Control Command.<\/p>", "group": "24-29", "lecture": "1", "href": "lesson.html#practice-24-29", "options": ["A sensor reports humidity", "A camera sends recorded video", "An application sends an unlock command", "A device reports battery level"], "correct": 2, "explanation": "أمر الفتح بيؤثر على سلوك الجهاز الفيزيائي، لذلك هو Control Command.", "persist": "lecture1-24-29-q2"}, {"id": "q-a1ecf32b9b37c6", "type": "mcq", "prompt": "Can an IoT system expose sensitive information without performing a physical action?", "answerHTML": "<p>A. Yes<\/p><p>ممكن يحصل Data Exposure حتى لو النظام ما بقدر ينفذ أي فعل فيزيائي.<\/p>", "group": "24-29", "lecture": "1", "href": "lesson.html#practice-24-29", "options": ["Yes", "No", "Only if it contains an actuator", "Only if it is industrial"], "correct": 0, "explanation": "ممكن يحصل Data Exposure حتى لو النظام ما بقدر ينفذ أي فعل فيزيائي.", "persist": "lecture1-24-29-q3"}, {"id": "q-6c7c5e0348902e", "type": "mcq", "prompt": "Which smart-building layer includes gateways and controllers?", "answerHTML": "<p>D. Local Layer<\/p><p>Controllers وGateways موجودين في Local Layer.<\/p>", "group": "24-29", "lecture": "1", "href": "lesson.html#practice-24-29", "options": ["Physical Layer", "Human Layer", "Remote Layer", "Local Layer"], "correct": 3, "explanation": "Controllers وGateways موجودين في Local Layer.", "persist": "lecture1-24-29-q4"}, {"id": "q-71ac5d90d0f5f0", "type": "mcq", "prompt": "Which layer includes dashboards, storage, and remote administration?", "answerHTML": "<p>B. Remote Layer<\/p><p>Remote Layer بتوفر وظائف الإدارة والتخزين والمراقبة عن بُعد.<\/p>", "group": "24-29", "lecture": "1", "href": "lesson.html#practice-24-29", "options": ["Physical Layer", "Remote Layer", "Human Layer", "Sensor Layer"], "correct": 1, "explanation": "Remote Layer بتوفر وظائف الإدارة والتخزين والمراقبة عن بُعد.", "persist": "lecture1-24-29-q5"}, {"id": "q-14702cb65e4863", "type": "mcq", "prompt": "A configuration error affects 15,000 identical IoT devices. Which challenge is illustrated?", "answerHTML": "<p>C. Scale<\/p><p>تكرار نفس الخطأ على عدد كبير من الأجهزة بوضح مشكلة Scale.<\/p>", "group": "24-29", "lecture": "1", "href": "lesson.html#practice-24-29", "options": ["Heterogeneity", "Physical Exposure", "Scale", "User Experience"], "correct": 2, "explanation": "تكرار نفس الخطأ على عدد كبير من الأجهزة بوضح مشكلة Scale.", "persist": "lecture1-24-29-q6"}, {"id": "q-b7589952da6b5e", "type": "mcq", "prompt": "Which activity means introducing and registering a new device in a deployment?", "answerHTML": "<p>A. Onboarding<\/p><p>Onboarding هي عملية إدخال الجهاز الجديد وتجهيزه ضمن النظام.<\/p>", "group": "24-29", "lecture": "1", "href": "lesson.html#practice-24-29", "options": ["Onboarding", "Retirement", "Telemetry", "Actuation"], "correct": 0, "explanation": "Onboarding هي عملية إدخال الجهاز الجديد وتجهيزه ضمن النظام.", "persist": "lecture1-24-29-q7"}, {"id": "q-e7c44eaa2b2692", "type": "mcq", "prompt": "Which process removes a device from active service?", "answerHTML": "<p>D. Retirement<\/p><p>Retirement تعني إخراج الجهاز من الخدمة.<\/p>", "group": "24-29", "lecture": "1", "href": "lesson.html#practice-24-29", "options": ["Inventory", "Communication", "Maintenance", "Retirement"], "correct": 3, "explanation": "Retirement تعني إخراج الجهاز من الخدمة.", "persist": "lecture1-24-29-q8"}, {"id": "q-a25a6f7219731f", "type": "mcq", "prompt": "Why may security assumptions become outdated during a device's lifetime?", "answerHTML": "<p>B. Networks, services, software dependencies, and ownership may change<\/p><p>البيئة المحيطة بالجهاز ممكن تتغير خلال سنوات تشغيله.<\/p>", "group": "24-29", "lecture": "1", "href": "lesson.html#practice-24-29", "options": ["Sensors always stop working", "Networks, services, software dependencies, and ownership may change", "IoT devices never receive maintenance", "All devices use identical software"], "correct": 1, "explanation": "البيئة المحيطة بالجهاز ممكن تتغير خلال سنوات تشغيله.", "persist": "lecture1-24-29-q9"}, {"id": "q-dcd55b7a870db8", "type": "mcq", "prompt": "What should organizations know about long-deployed IoT devices?", "answerHTML": "<p>C. Which devices exist and whether they remain supportable<\/p><p>Visibility وSupportability نقطتان أساسيتان في السلايد.<\/p>", "group": "24-29", "lecture": "1", "href": "lesson.html#practice-24-29", "options": ["Only their purchase price", "Only their physical color", "Which devices exist and whether they remain supportable", "Only the number of users"], "correct": 2, "explanation": "Visibility وSupportability نقطتان أساسيتان في السلايد.", "persist": "lecture1-24-29-q10"}, {"id": "q-0eecb1789b6173", "type": "mcq", "prompt": "A patient sensor sends incorrect measurements to clinical staff. Which concern is most directly illustrated?", "answerHTML": "<p>A. Incorrect Data<\/p><p>المشكلة الأساسية هي Incorrect Data، لأنها مرتبطة بصحة القياسات.<\/p>", "group": "24-29", "lecture": "1", "href": "lesson.html#practice-24-29", "options": ["Incorrect Data", "Scale", "Retirement", "Physical Actuation"], "correct": 0, "explanation": "المشكلة الأساسية هي Incorrect Data، لأنها مرتبطة بصحة القياسات.", "persist": "lecture1-24-29-q11"}, {"id": "q-198fb70ef325ef", "type": "mcq", "prompt": "Which conclusion about the medical sensor scenario is most appropriate?", "answerHTML": "<p>D. The importance of each consequence depends on the system&#x27;s functions and context<\/p><p>لازم نحلل الوظائف الفعلية للجهاز، وما نفترض وجود Actuation أو Gateway بدون دليل.<\/p>", "group": "24-29", "lecture": "1", "href": "lesson.html#practice-24-29", "options": ["Every sensor necessarily controls treatment", "Data exposure is the only relevant concern", "The system definitely includes a gateway", "The importance of each consequence depends on the system's functions and context"], "correct": 3, "explanation": "لازم نحلل الوظائف الفعلية للجهاز، وما نفترض وجود Actuation أو Gateway بدون دليل.", "persist": "lecture1-24-29-q12"}, {"id": "q-3fb93ba27fe3c7", "type": "blank", "prompt": "_______ flows from the physical environment toward applications and services.", "answerHTML": "<p>Telemetry<\/p>", "group": "24-29", "lecture": "1", "href": "lesson.html#practice-24-29", "answer": "Telemetry"}, {"id": "q-3d068d3f956567", "type": "blank", "prompt": "Control commands may influence device _______.", "answerHTML": "<p>behavior<\/p>", "group": "24-29", "lecture": "1", "href": "lesson.html#practice-24-29", "answer": "behavior"}, {"id": "q-6b4b55a26b43e2", "type": "blank", "prompt": "A system can expose sensitive _______ without performing physical actions.", "answerHTML": "<p>data<\/p>", "group": "24-29", "lecture": "1", "href": "lesson.html#practice-24-29", "answer": "data"}, {"id": "q-fd4d59688e3d71", "type": "blank", "prompt": "Door sensors and cameras belong to the _______ layer.", "answerHTML": "<p>Physical<\/p>", "group": "24-29", "lecture": "1", "href": "lesson.html#practice-24-29", "answer": "Physical"}, {"id": "q-0e98dc8bc7007d", "type": "blank", "prompt": "Controllers and gateways belong to the _______ layer.", "answerHTML": "<p>Local<\/p>", "group": "24-29", "lecture": "1", "href": "lesson.html#practice-24-29", "answer": "Local"}, {"id": "q-b571890f1e7c7e", "type": "blank", "prompt": "Dashboards and remote administration belong to the _______ layer.", "answerHTML": "<p>Remote<\/p>", "group": "24-29", "lecture": "1", "href": "lesson.html#practice-24-29", "answer": "Remote"}, {"id": "q-8a6497a5bc8cf4", "type": "blank", "prompt": "Employees and administrators belong to the _______ layer.", "answerHTML": "<p>Human<\/p>", "group": "24-29", "lecture": "1", "href": "lesson.html#practice-24-29", "answer": "Human"}, {"id": "q-11f5b16432b7aa", "type": "blank", "prompt": "A repeated configuration mistake across thousands of devices illustrates _______.", "answerHTML": "<p>Scale<\/p>", "group": "24-29", "lecture": "1", "href": "lesson.html#practice-24-29", "answer": "Scale"}, {"id": "q-fd3599b1b2d8b9", "type": "blank", "prompt": "The process of introducing devices into a deployment is called _______.", "answerHTML": "<p>Onboarding<\/p>", "group": "24-29", "lecture": "1", "href": "lesson.html#practice-24-29", "answer": "Onboarding"}, {"id": "q-a26eb896301d60", "type": "blank", "prompt": "Maintaining a record of deployed devices is called _______.", "answerHTML": "<p>Inventory<\/p>", "group": "24-29", "lecture": "1", "href": "lesson.html#practice-24-29", "answer": "Inventory"}, {"id": "q-bfb801eb747bd2", "type": "blank", "prompt": "Removing a device from active service is called _______.", "answerHTML": "<p>Retirement<\/p>", "group": "24-29", "lecture": "1", "href": "lesson.html#practice-24-29", "answer": "Retirement"}, {"id": "q-3e673dc065e1e6", "type": "blank", "prompt": "Organizations should know whether deployed devices remain _______.", "answerHTML": "<p>Supportable<\/p>", "group": "24-29", "lecture": "1", "href": "lesson.html#practice-24-29", "answer": "Supportable"}, {"id": "q-f3d1184f3e870d", "type": "short", "prompt": "Q1. Identify four attack-surface elements.", "answerHTML": "<p>Answer: Maintenance port, wireless interface, cloud service interface, and mobile application interface.<\/p>", "group": "32", "lecture": "2", "href": "lesson.html#slide-32", "context": "A smart camera has a maintenance port, wireless communication, a cloud service, and a mobile application."}, {"id": "q-cbe5bbf8bed563", "type": "short", "prompt": "Q2. Does the existence of these interfaces prove that the camera is insecure?", "answerHTML": "<p>Answer: No. A larger attack surface does not automatically mean that a system is insecure.<\/p>", "group": "32", "lecture": "2", "href": "lesson.html#slide-32", "context": "A smart camera has a maintenance port, wireless communication, a cloud service, and a mobile application."}, {"id": "q-6c6d3bf24403d0", "type": "short", "prompt": "Q3. What is the purpose of attack-surface mapping?", "answerHTML": "<p>Answer: To identify and understand the system's exposure and interaction points.<\/p><p>التحليل بالعربي: السؤال مش بطلب منك تذكر هجوم. هو بطلب تحدد الأماكن اللي ممكن يصير فيها تفاعل مع النظام.<\/p>", "group": "32", "lecture": "2", "href": "lesson.html#slide-32", "context": "A smart camera has a maintenance port, wireless communication, a cloud service, and a mobile application."}, {"id": "q-cebba58237cc51", "type": "short", "prompt": "Q1. Identify five attack-surface areas.", "answerHTML": "<p>Answer: Hardware, Firmware, Radio / Network, Cloud / API, and Application / Human.<\/p>", "group": "33", "lecture": "2", "href": "lesson.html#slide-33", "context": "A smart lock contains an embedded processor, firmware, wireless communication, a cloud service, and a mobile application. An installer can physically access the device."}, {"id": "q-658bc40d704500", "type": "short", "prompt": "Q2. Which area includes wireless communication?", "answerHTML": "<p>Answer: Radio / Network.<\/p>", "group": "33", "lecture": "2", "href": "lesson.html#slide-33", "context": "A smart lock contains an embedded processor, firmware, wireless communication, a cloud service, and a mobile application. An installer can physically access the device."}, {"id": "q-d1b0ca22eb7133", "type": "short", "prompt": "Q3. Which area includes the mobile application and user workflows?", "answerHTML": "<p>Answer: Application / Human.<\/p>", "group": "33", "lecture": "2", "href": "lesson.html#slide-33", "context": "A smart lock contains an embedded processor, firmware, wireless communication, a cloud service, and a mobile application. An installer can physically access the device."}, {"id": "q-fde12300546e14", "type": "short", "prompt": "Q4. Which area includes device boot code?", "answerHTML": "<p>Answer: Firmware.<\/p><p>ملاحظة: لا تضيف Gateway للإجابة إلا إذا السيناريو ذكره أو كان واضحًا من تصميم النظام.<\/p>", "group": "33", "lecture": "2", "href": "lesson.html#slide-33", "context": "A smart lock contains an embedded processor, firmware, wireless communication, a cloud service, and a mobile application. An installer can physically access the device."}, {"id": "q-692e90bbec403f", "type": "short", "prompt": "Q1. Which attack-surface area is most relevant?", "answerHTML": "<p>Answer: Hardware Surface.<\/p>", "group": "35", "lecture": "2", "href": "lesson.html#slide-35", "context": "A smart environmental sensor is installed in a public area. The device contains a processor, memory, and a physical debugging interface."}, {"id": "q-d71f5b0ae4ec52", "type": "short", "prompt": "Q2. What should a security engineer identify?", "answerHTML": "<p>Answer: The existing hardware interfaces and who can physically access them.<\/p>", "group": "35", "lecture": "2", "href": "lesson.html#slide-35", "context": "A smart environmental sensor is installed in a public area. The device contains a processor, memory, and a physical debugging interface."}, {"id": "q-b43cf0611f62d2", "type": "short", "prompt": "Q3. Does the presence of a debugging interface automatically prove a vulnerability?", "answerHTML": "<p>Answer: No. It is an interface that should be identified and understood.<\/p><p>الشرح بالعربي: السؤال بيركز على الوصول الفيزيائي والواجهات الموجودة بالجهاز، مش على تفاصيل استغلالها.<\/p>", "group": "35", "lecture": "2", "href": "lesson.html#slide-35", "context": "A smart environmental sensor is installed in a public area. The device contains a processor, memory, and a physical debugging interface."}, {"id": "q-24c87ebac281ab", "type": "mcq", "prompt": "What is the attack surface of an IoT system?", "answerHTML": "<p>B. The collection of places where unauthorized or unintended interaction could occur<\/p><p>التعريف الرسمي بيركز على أماكن التفاعل غير المصرّح أو غير المقصود، مش فقط الثغرات أو المنافذ.<\/p>", "group": "30-35", "lecture": "2", "href": "lesson.html#practice-30-35", "options": ["Only known software vulnerabilities", "The collection of places where unauthorized or unintended interaction could occur", "Only open network ports", "Only physical hardware"], "correct": 1, "explanation": "التعريف الرسمي بيركز على أماكن التفاعل غير المصرّح أو غير المقصود، مش فقط الثغرات أو المنافذ.", "persist": "lecture2-30-35-q1"}, {"id": "q-c267b73fbf24be", "type": "mcq", "prompt": "Does a larger attack surface automatically mean a system is insecure?", "answerHTML": "<p>C. No, it means more exposure to understand and manage<\/p><p>كبر سطح الهجوم يعني نقاط تعرّض أكثر لازم نفهمها ونديرها، ولا يثبت أن النظام غير آمن.<\/p>", "group": "30-35", "lecture": "2", "href": "lesson.html#practice-30-35", "options": ["Yes, always", "Only for industrial IoT", "No, it means more exposure to understand and manage", "Only when a cloud service is used"], "correct": 2, "explanation": "كبر سطح الهجوم يعني نقاط تعرّض أكثر لازم نفهمها ونديرها، ولا يثبت أن النظام غير آمن.", "persist": "lecture2-30-35-q2"}, {"id": "q-28e280f613b405", "type": "mcq", "prompt": "Which of the following is NOT excluded from IoT attack-surface mapping?", "answerHTML": "<p>A. Human workflows<\/p><p>Human Workflows جزء أساسي من Attack Surface، مثل الإعداد والصيانة واستعادة الحساب.<\/p>", "group": "30-35", "lecture": "2", "href": "lesson.html#practice-30-35", "options": ["Human workflows", "Only network ports", "Only wireless connections", "Only firmware"], "correct": 0, "explanation": "Human Workflows جزء أساسي من Attack Surface، مثل الإعداد والصيانة واستعادة الحساب.", "persist": "lecture2-30-35-q3"}, {"id": "q-0a847839edb9c7", "type": "mcq", "prompt": "Which attack-surface area includes UART, JTAG, and flash?", "answerHTML": "<p>D. Hardware<\/p><p>UART وJTAG وFlash موجودة ضمن Hardware في مخطط المحاضرة.<\/p>", "group": "30-35", "lecture": "2", "href": "lesson.html#practice-30-35", "options": ["Cloud / API", "App / Human", "Gateway", "Hardware"], "correct": 3, "explanation": "UART وJTAG وFlash موجودة ضمن Hardware في مخطط المحاضرة.", "persist": "lecture2-30-35-q4"}, {"id": "q-87f6c4d6ca4607", "type": "mcq", "prompt": "Which attack-surface area includes boot, secrets, and code?", "answerHTML": "<p>A. Firmware<\/p><p>Boot وSecrets وCode أمثلة Firmware Surface.<\/p>", "group": "30-35", "lecture": "2", "href": "lesson.html#practice-30-35", "options": ["Firmware", "Gateway", "Radio / Network", "Human"], "correct": 0, "explanation": "Boot وSecrets وCode أمثلة Firmware Surface.", "persist": "lecture2-30-35-q5"}, {"id": "q-78c72361140157", "type": "mcq", "prompt": "What does BLE stand for?", "answerHTML": "<p>B. Bluetooth Low Energy<\/p><p>BLE = Bluetooth Low Energy، وهي تقنية اتصال منخفضة الطاقة وقصيرة المدى.<\/p>", "group": "30-35", "lecture": "2", "href": "lesson.html#practice-30-35", "options": ["Basic Local Ethernet", "Bluetooth Low Energy", "Binary Link Exchange", "Bluetooth Logical Extension"], "correct": 1, "explanation": "BLE = Bluetooth Low Energy، وهي تقنية اتصال منخفضة الطاقة وقصيرة المدى.", "persist": "lecture2-30-35-q6"}, {"id": "q-d55b98cb41fb11", "type": "mcq", "prompt": "Which interface is commonly used for serial communication and debugging?", "answerHTML": "<p>C. UART<\/p><p>UART واجهة اتصال تسلسلي مستخدمة في التواصل وفحص المشكلات.<\/p>", "group": "30-35", "lecture": "2", "href": "lesson.html#practice-30-35", "options": ["UX", "API", "UART", "IP"], "correct": 2, "explanation": "UART واجهة اتصال تسلسلي مستخدمة في التواصل وفحص المشكلات.", "persist": "lecture2-30-35-q7"}, {"id": "q-25e4d232de5925", "type": "mcq", "prompt": "Which interface may provide low-level hardware testing and debugging access?", "answerHTML": "<p>D. JTAG<\/p><p>JTAG مرتبطة بفحص الأجهزة وتصحيح المشكلات والوصول منخفض المستوى.<\/p>", "group": "30-35", "lecture": "2", "href": "lesson.html#practice-30-35", "options": ["BLE", "API", "UX", "JTAG"], "correct": 3, "explanation": "JTAG مرتبطة بفحص الأجهزة وتصحيح المشكلات والوصول منخفض المستوى.", "persist": "lecture2-30-35-q8"}, {"id": "q-ed4d1d9fdab5de", "type": "mcq", "prompt": "What does API stand for?", "answerHTML": "<p>A. Application Programming Interface<\/p><p>API = Application Programming Interface.<\/p>", "group": "30-35", "lecture": "2", "href": "lesson.html#practice-30-35", "options": ["Application Programming Interface", "Automatic Processing Interface", "Application Protection Internet", "Advanced Protocol Integration"], "correct": 0, "explanation": "API = Application Programming Interface.", "persist": "lecture2-30-35-q9"}, {"id": "q-a4403598e0900d", "type": "mcq", "prompt": "What is the key Week 1 question for the hardware surface?", "answerHTML": "<p>B. What hardware interfaces exist and who can physically reach them?<\/p><p>في Week 1 بنحدد الواجهات والأشخاص القادرين على الوصول، مش تفاصيل الهجمات.<\/p>", "group": "30-35", "lecture": "2", "href": "lesson.html#practice-30-35", "options": ["Which exploit is most effective?", "What hardware interfaces exist and who can physically reach them?", "How can firmware encryption be bypassed?", "How can a network be scanned?"], "correct": 1, "explanation": "في Week 1 بنحدد الواجهات والأشخاص القادرين على الوصول، مش تفاصيل الهجمات.", "persist": "lecture2-30-35-q10"}, {"id": "q-af19938e427ceb", "type": "blank", "prompt": "The attack surface is the collection of places where an unauthorized or _______ interaction could occur.", "answerHTML": "<p>unintended<\/p>", "group": "30-35", "lecture": "2", "href": "lesson.html#practice-30-35", "answer": "unintended"}, {"id": "q-fb4d8adca5aea3", "type": "blank", "prompt": "A larger attack surface does not automatically mean a system is _______.", "answerHTML": "<p>insecure<\/p>", "group": "30-35", "lecture": "2", "href": "lesson.html#practice-30-35", "answer": "insecure"}, {"id": "q-813ba36bd29458", "type": "blank", "prompt": "The IoT attack surface includes physical interfaces, software interfaces, communication paths, service interfaces, and human _______.", "answerHTML": "<p>workflows<\/p>", "group": "30-35", "lecture": "2", "href": "lesson.html#practice-30-35", "answer": "workflows"}, {"id": "q-a4534209a3e1a5", "type": "blank", "prompt": "UART stands for Universal Asynchronous _______/Transmitter.", "answerHTML": "<p>Receiver<\/p>", "group": "30-35", "lecture": "2", "href": "lesson.html#practice-30-35", "answer": "Receiver"}, {"id": "q-f7532aaf103a52", "type": "blank", "prompt": "JTAG stands for Joint Test Action _______.", "answerHTML": "<p>Group<\/p>", "group": "30-35", "lecture": "2", "href": "lesson.html#practice-30-35", "answer": "Group"}, {"id": "q-fec7a11c692111", "type": "blank", "prompt": "BLE stands for Bluetooth Low _______.", "answerHTML": "<p>Energy<\/p>", "group": "30-35", "lecture": "2", "href": "lesson.html#practice-30-35", "answer": "Energy"}, {"id": "q-751b0ffffa72a2", "type": "blank", "prompt": "IP stands for Internet _______.", "answerHTML": "<p>Protocol<\/p>", "group": "30-35", "lecture": "2", "href": "lesson.html#practice-30-35", "answer": "Protocol"}, {"id": "q-bc2377e7e78fc7", "type": "blank", "prompt": "API stands for Application Programming _______.", "answerHTML": "<p>Interface<\/p>", "group": "30-35", "lecture": "2", "href": "lesson.html#practice-30-35", "answer": "Interface"}, {"id": "q-ff0aa3dd20ee44", "type": "blank", "prompt": "UX stands for User _______.", "answerHTML": "<p>Experience<\/p>", "group": "30-35", "lecture": "2", "href": "lesson.html#practice-30-35", "answer": "Experience"}, {"id": "q-6546c328ba8635", "type": "blank", "prompt": "Hardware includes processors, memory, storage, sensors, actuators, ports, and physical test or _______ interfaces.", "answerHTML": "<p>debug<\/p>", "group": "30-35", "lecture": "2", "href": "lesson.html#practice-30-35", "answer": "debug"}, {"id": "q-4e5aff86d5f03d", "type": "short", "prompt": "Q1. Which attack-surface area is described?", "answerHTML": "<p><strong>Answer:<\/strong> Firmware Surface.<\/p>", "group": "36", "lecture": "2", "href": "lesson.html#slide-36", "context": "A smart camera contains embedded software, device identifiers, configuration settings, and software libraries."}, {"id": "q-0ffa84eb3de2a5", "type": "short", "prompt": "Q2. Identify three elements stored in the firmware.", "answerHTML": "<p><strong>Answer:<\/strong> Device Identifiers, Configuration, and Software Libraries.<\/p>", "group": "36", "lecture": "2", "href": "lesson.html#slide-36", "context": "A smart camera contains embedded software, device identifiers, configuration settings, and software libraries."}, {"id": "q-7f118de4cf2a71", "type": "short", "prompt": "Q3. What is the main Week 1 security question?", "answerHTML": "<p><strong>Answer:<\/strong> What software exists on the device and how is it managed?<\/p><p><strong>التحليل:<\/strong> الكلمات <em>Embedded Software<\/em> و<em>Configuration<\/em> و<em>Libraries<\/em> بتدل مباشرة على Firmware.<\/p>", "group": "36", "lecture": "2", "href": "lesson.html#slide-36", "context": "A smart camera contains embedded software, device identifiers, configuration settings, and software libraries."}, {"id": "q-7eb022d846b7ef", "type": "short", "prompt": "Q1. Which attack-surface area is involved?", "answerHTML": "<p><strong>Answer:<\/strong> Radio / Network Surface.<\/p>", "group": "37", "lecture": "2", "href": "lesson.html#slide-37", "context": "An IoT sensor communicates with a nearby gateway over a local wireless connection. The gateway forwards data to a remote service."}, {"id": "q-f326a7a6637139", "type": "short", "prompt": "Q2. Identify two communication paths.", "answerHTML": "<p><strong>Answer:<\/strong> Sensor to Gateway, and Gateway to Remote Service.<\/p>", "group": "37", "lecture": "2", "href": "lesson.html#slide-37", "context": "An IoT sensor communicates with a nearby gateway over a local wireless connection. The gateway forwards data to a remote service."}, {"id": "q-85aa0202675440", "type": "short", "prompt": "Q3. What should the security engineer determine?", "answerHTML": "<p><strong>Answer:<\/strong> Who can communicate with the device, from where, and through which path.<\/p>", "group": "37", "lecture": "2", "href": "lesson.html#slide-37", "context": "An IoT sensor communicates with a nearby gateway over a local wireless connection. The gateway forwards data to a remote service."}, {"id": "q-5c4839788b379b", "type": "short", "prompt": "Q1. Which component is a shared dependency?", "answerHTML": "<p><strong>Answer:<\/strong> The Gateway.<\/p>", "group": "38", "lecture": "2", "href": "lesson.html#slide-38", "context": "A factory has 200 sensors connected to one gateway. The gateway forwards measurements to a remote monitoring service."}, {"id": "q-4b3470c836e58a", "type": "short", "prompt": "Q2. What functions may depend on the gateway?", "answerHTML": "<p><strong>Answer:<\/strong> Communication, Management, and Local Processing.<\/p>", "group": "38", "lecture": "2", "href": "lesson.html#slide-38", "context": "A factory has 200 sensors connected to one gateway. The gateway forwards measurements to a remote monitoring service."}, {"id": "q-4506a4f6edaf81", "type": "short", "prompt": "Q3. What is the main security question?", "answerHTML": "<p><strong>Answer:<\/strong> What devices and services trust the gateway?<\/p>", "group": "38", "lecture": "2", "href": "lesson.html#slide-38", "context": "A factory has 200 sensors connected to one gateway. The gateway forwards measurements to a remote monitoring service."}, {"id": "q-c6f177b5a8f7a8", "type": "short", "prompt": "Q4. If the gateway fails, must every sensor stop measuring?", "answerHTML": "<p><strong>Answer:<\/strong> Not necessarily. The impact depends on which functions rely on the gateway.<\/p><p><strong>الشرح:<\/strong> فرّق بين استمرار وظيفة الحساس محليًا وبين قدرته على إرسال القياسات للخدمة البعيدة.<\/p>", "group": "38", "lecture": "2", "href": "lesson.html#slide-38", "context": "A factory has 200 sensors connected to one gateway. The gateway forwards measurements to a remote monitoring service."}, {"id": "q-23088c8e7037ce", "type": "short", "prompt": "Q1. Which attack-surface area is illustrated?", "answerHTML": "<p><strong>Answer:<\/strong> Cloud / API Surface.<\/p>", "group": "39", "lecture": "2", "href": "lesson.html#slide-39", "context": "A smart camera uses a cloud service to store recordings, manage user accounts, and send device commands through an API."}, {"id": "q-1be638a1c7019a", "type": "short", "prompt": "Q2. Identify three remote functions.", "answerHTML": "<p><strong>Answer:<\/strong> Data Storage, User Management, and Command Delivery.<\/p>", "group": "39", "lecture": "2", "href": "lesson.html#slide-39", "context": "A smart camera uses a cloud service to store recordings, manage user accounts, and send device commands through an API."}, {"id": "q-eacb1e60b2db88", "type": "short", "prompt": "Q3. What does API stand for?", "answerHTML": "<p><strong>Answer:<\/strong> Application Programming Interface.<\/p>", "group": "39", "lecture": "2", "href": "lesson.html#slide-39", "context": "A smart camera uses a cloud service to store recordings, manage user accounts, and send device commands through an API."}, {"id": "q-790f9f131caa7b", "type": "short", "prompt": "Q4. What is the main Week 1 question?", "answerHTML": "<p><strong>Answer:<\/strong> What remote functions can affect the device or its data?<\/p><p><strong>ملاحظة من السلايد:<\/strong> تفاصيل حماية Cloud وAPI رح تنشرح في Week 11.<\/p>", "group": "39", "lecture": "2", "href": "lesson.html#slide-39", "context": "A smart camera uses a cloud service to store recordings, manage user accounts, and send device commands through an API."}, {"id": "q-ad5fec6a257e46", "type": "short", "prompt": "Q1. Which attack-surface area is illustrated?", "answerHTML": "<p><strong>Answer:<\/strong> Application / Human Surface.<\/p>", "group": "40", "lecture": "2", "href": "lesson.html#slide-40", "context": "A smart-home application allows users to view devices, share access with family members, and recover their accounts. Installers also use a maintenance interface."}, {"id": "q-b939d2378bc03e", "type": "short", "prompt": "Q2. Identify three human workflows.", "answerHTML": "<p><strong>Answer:<\/strong> Sharing, Account Recovery, and Maintenance.<\/p>", "group": "40", "lecture": "2", "href": "lesson.html#slide-40", "context": "A smart-home application allows users to view devices, share access with family members, and recover their accounts. Installers also use a maintenance interface."}, {"id": "q-b0a957bd9ff070", "type": "short", "prompt": "Q3. What is the main security question?", "answerHTML": "<p><strong>Answer:<\/strong> Which people can perform which actions through which interface?<\/p><p><strong>ملاحظة:<\/strong> تفاصيل Authentication وAuthorization رح تنشرح في Week 2.<\/p>", "group": "40", "lecture": "2", "href": "lesson.html#slide-40", "context": "A smart-home application allows users to view devices, share access with family members, and recover their accounts. Installers also use a maintenance interface."}, {"id": "q-615d7db4054366", "type": "short", "prompt": "Q1. Identify one Asset.", "answerHTML": "<p><strong>Answer:<\/strong> Correct Lock Operation.<\/p>", "group": "41", "lecture": "2", "href": "lesson.html#slide-41", "context": "A smart door lock uses a mobile application to send commands through a cloud service. The cloud service is required for remote control, and the correct operation of the lock must be protected."}, {"id": "q-c43169816b76a9", "type": "short", "prompt": "Q2. Identify one Interface.", "answerHTML": "<p><strong>Answer:<\/strong> Mobile Application Interface.<\/p>", "group": "41", "lecture": "2", "href": "lesson.html#slide-41", "context": "A smart door lock uses a mobile application to send commands through a cloud service. The cloud service is required for remote control, and the correct operation of the lock must be protected."}, {"id": "q-b5dc17071912a4", "type": "short", "prompt": "Q3. Identify one Dependency.", "answerHTML": "<p><strong>Answer:<\/strong> Cloud Service for Remote Control.<\/p>", "group": "41", "lecture": "2", "href": "lesson.html#slide-41", "context": "A smart door lock uses a mobile application to send commands through a cloud service. The cloud service is required for remote control, and the correct operation of the lock must be protected."}, {"id": "q-769bb1ffd989c5", "type": "short", "prompt": "Q4. Identify one Trust Boundary.", "answerHTML": "<p><strong>Answer:<\/strong> Mobile Application ↔ Cloud Service, where different trust assumptions may apply.<\/p><p><strong>التحليل:<\/strong> نفس النظام ممكن يحتوي على الأربعة معًا. المطلوب تعرف وظيفة كل مفهوم، مش تحفظ اسم المكوّن لحاله.<\/p>", "group": "41", "lecture": "2", "href": "lesson.html#slide-41", "context": "A smart door lock uses a mobile application to send commands through a cloud service. The cloud service is required for remote control, and the correct operation of the lock must be protected."}, {"id": "q-632fb6ae640503", "type": "mcq", "prompt": "What does firmware include according to the lecture?", "answerHTML": "<p>B. Software and configuration stored on or executed by the device<\/p><p>Firmware يشمل البرمجيات والإعدادات المخزنة على الجهاز أو اللي الجهاز بنفذها.<\/p>", "group": "36-41", "lecture": "2", "href": "lesson.html#practice-36-41", "options": ["Only physical sensors", "Software and configuration stored on or executed by the device", "Only cloud applications", "Only wireless connections"], "correct": 1, "explanation": "Firmware يشمل البرمجيات والإعدادات المخزنة على الجهاز أو اللي الجهاز بنفذها.", "persist": "lecture2-36-41-q1"}, {"id": "q-c86d824a76b2ee", "type": "mcq", "prompt": "Which of the following may be contained in firmware?", "answerHTML": "<p>A. Device logic, identifiers, configuration, and libraries<\/p><p>السلايد بذكر Device Logic وIdentifiers وConfiguration وLibraries.<\/p>", "group": "36-41", "lecture": "2", "href": "lesson.html#practice-36-41", "options": ["Device logic, identifiers, configuration, and libraries", "Only external cloud servers", "Only physical cables", "Only human workflows"], "correct": 0, "explanation": "السلايد بذكر Device Logic وIdentifiers وConfiguration وLibraries.", "persist": "lecture2-36-41-q2"}, {"id": "q-1e29715ae4b3a0", "type": "mcq", "prompt": "What is the main Week 1 question about firmware?", "answerHTML": "<p>C. What software exists on the device and how is it managed?<\/p><p>Week 1 بيركز على تحديد البرمجيات وكيف بتتم إدارتها، مش طرق الهجوم.<\/p>", "group": "36-41", "lecture": "2", "href": "lesson.html#practice-36-41", "options": ["How to exploit firmware?", "How to bypass Secure Boot?", "What software exists on the device and how is it managed?", "How to break firmware signatures?"], "correct": 2, "explanation": "Week 1 بيركز على تحديد البرمجيات وكيف بتتم إدارتها، مش طرق الهجوم.", "persist": "lecture2-36-41-q3"}, {"id": "q-4da7b8edfd045c", "type": "mcq", "prompt": "Which question best describes the Radio / Network Surface?", "answerHTML": "<p>A. Who can communicate with the device, from where, and through which path?<\/p><p>السؤال الرئيسي هو Who, From Where, Through Which Path.<\/p>", "group": "36-41", "lecture": "2", "href": "lesson.html#practice-36-41", "options": ["Who can communicate with the device, from where, and through which path?", "Who manufactured the processor?", "How much storage does the cloud have?", "Who designed the user interface?"], "correct": 0, "explanation": "السؤال الرئيسي هو Who, From Where, Through Which Path.", "persist": "lecture2-36-41-q4"}, {"id": "q-11dee9573a8d5a", "type": "mcq", "prompt": "A gateway connects many local sensors to a remote service. What can it become?", "answerHTML": "<p>D. A shared dependency<\/p><p>Gateway ممكن يكون Shared Dependency للاتصال أو الإدارة أو المعالجة المحلية.<\/p>", "group": "36-41", "lecture": "2", "href": "lesson.html#practice-36-41", "options": ["An actuator", "A user interface", "A firmware library", "A shared dependency"], "correct": 3, "explanation": "Gateway ممكن يكون Shared Dependency للاتصال أو الإدارة أو المعالجة المحلية.", "persist": "lecture2-36-41-q5"}, {"id": "q-b211f60db22447", "type": "mcq", "prompt": "Which function may be provided by a cloud service?", "answerHTML": "<p>B. Device registration and user management<\/p><p>Cloud ممكن يسجل الأجهزة ويدير المستخدمين ويخزن البيانات ويرسل الأوامر.<\/p>", "group": "36-41", "lecture": "2", "href": "lesson.html#practice-36-41", "options": ["Physical sensing only", "Device registration and user management", "Hardware testing only", "Local battery replacement"], "correct": 1, "explanation": "Cloud ممكن يسجل الأجهزة ويدير المستخدمين ويخزن البيانات ويرسل الأوامر.", "persist": "lecture2-36-41-q6"}, {"id": "q-b58ee056b8c163", "type": "mcq", "prompt": "What does API stand for?", "answerHTML": "<p>C. Application Programming Interface<\/p><p>API = Application Programming Interface.<\/p>", "group": "36-41", "lecture": "2", "href": "lesson.html#practice-36-41", "options": ["Advanced Processing Integration", "Automatic Protection Interface", "Application Programming Interface", "Application Physical Interaction"], "correct": 2, "explanation": "API = Application Programming Interface.", "persist": "lecture2-36-41-q7"}, {"id": "q-4fa7d350d37bf5", "type": "mcq", "prompt": "Which of the following is a human workflow?", "answerHTML": "<p>A. Account recovery<\/p><p>Account Recovery من أمثلة Human Workflows المذكورة في Slide 40.<\/p>", "group": "36-41", "lecture": "2", "href": "lesson.html#practice-36-41", "options": ["Account recovery", "Processor execution", "Sensor measurement", "Radio transmission"], "correct": 0, "explanation": "Account Recovery من أمثلة Human Workflows المذكورة في Slide 40.", "persist": "lecture2-36-41-q8"}, {"id": "q-20ed99f6dedc2d", "type": "mcq", "prompt": "Which term describes something valuable that must be protected or kept functioning?", "answerHTML": "<p>D. Asset<\/p><p>Asset هو الشيء ذو القيمة اللي لازم نحميه أو نحافظ على تشغيله.<\/p>", "group": "36-41", "lecture": "2", "href": "lesson.html#practice-36-41", "options": ["Interface", "Dependency", "Trust Boundary", "Asset"], "correct": 3, "explanation": "Asset هو الشيء ذو القيمة اللي لازم نحميه أو نحافظ على تشغيله.", "persist": "lecture2-36-41-q9"}, {"id": "q-26cf97d90848fe", "type": "mcq", "prompt": "A point through which a component communicates or can be accessed is called:", "answerHTML": "<p>B. Interface<\/p><p>هذا تعريف Interface من السلايد.<\/p>", "group": "36-41", "lecture": "2", "href": "lesson.html#practice-36-41", "options": ["Asset", "Interface", "Dependency", "Trust Boundary"], "correct": 1, "explanation": "هذا تعريف Interface من السلايد.", "persist": "lecture2-36-41-q10"}, {"id": "q-434b63faf2e192", "type": "mcq", "prompt": "Another component or service required for correct operation is called:", "answerHTML": "<p>C. Dependency<\/p><p>هذا تعريف Dependency من المحاضرة.<\/p>", "group": "36-41", "lecture": "2", "href": "lesson.html#practice-36-41", "options": ["Asset", "Interface", "Dependency", "Trust Boundary"], "correct": 2, "explanation": "هذا تعريف Dependency من المحاضرة.", "persist": "lecture2-36-41-q11"}, {"id": "q-52bebb6461a95d", "type": "mcq", "prompt": "Where do data, commands, identity, or control cross areas with different trust assumptions?", "answerHTML": "<p>A. Trust Boundary<\/p><p>هذا تعريف Trust Boundary، ولازم تركز على Different Trust Assumptions.<\/p>", "group": "36-41", "lecture": "2", "href": "lesson.html#practice-36-41", "options": ["Trust Boundary", "Firmware Library", "Device Inventory", "Physical Sensor"], "correct": 0, "explanation": "هذا تعريف Trust Boundary، ولازم تركز على Different Trust Assumptions.", "persist": "lecture2-36-41-q12"}, {"id": "q-ea6c5b9d54cec2", "type": "blank", "prompt": "Firmware includes software and _______ stored on or executed by the device.", "answerHTML": "<p>configuration<\/p>", "group": "36-41", "lecture": "2", "href": "lesson.html#practice-36-41", "answer": "configuration"}, {"id": "q-b1dfd6a030c223", "type": "blank", "prompt": "Firmware may contain device logic, identifiers, configuration, and _______.", "answerHTML": "<p>libraries<\/p>", "group": "36-41", "lecture": "2", "href": "lesson.html#practice-36-41", "answer": "libraries"}, {"id": "q-eb17f650fe05d9", "type": "blank", "prompt": "Connected devices exchange data and _______ through communication paths.", "answerHTML": "<p>commands<\/p>", "group": "36-41", "lecture": "2", "href": "lesson.html#practice-36-41", "answer": "commands"}, {"id": "q-4a2e8487d8a22c", "type": "blank", "prompt": "Each reachable interface creates an _______ point.", "answerHTML": "<p>interaction<\/p>", "group": "36-41", "lecture": "2", "href": "lesson.html#practice-36-41", "answer": "interaction"}, {"id": "q-f4689b4ae3663e", "type": "blank", "prompt": "A gateway can become a shared _______ for multiple devices.", "answerHTML": "<p>dependency<\/p>", "group": "36-41", "lecture": "2", "href": "lesson.html#practice-36-41", "answer": "dependency"}, {"id": "q-a3e90a53cde44d", "type": "blank", "prompt": "APIs connect applications and services to _______ functions.", "answerHTML": "<p>backend<\/p>", "group": "36-41", "lecture": "2", "href": "lesson.html#practice-36-41", "answer": "backend"}, {"id": "q-bdfcd63bd37d3d", "type": "blank", "prompt": "Human workflows include setup, account recovery, sharing, installation, maintenance, and _______.", "answerHTML": "<p>support<\/p>", "group": "36-41", "lecture": "2", "href": "lesson.html#practice-36-41", "answer": "support"}, {"id": "q-1767721e652e0e", "type": "blank", "prompt": "An _______ is something valuable that must be protected or kept functioning.", "answerHTML": "<p>asset<\/p>", "group": "36-41", "lecture": "2", "href": "lesson.html#practice-36-41", "answer": "asset"}, {"id": "q-698d3a2c64f20a", "type": "blank", "prompt": "An _______ is a point through which a component communicates or can be accessed.", "answerHTML": "<p>interface<\/p>", "group": "36-41", "lecture": "2", "href": "lesson.html#practice-36-41", "answer": "interface"}, {"id": "q-a389848e839ebc", "type": "blank", "prompt": "A _______ is another component or service required for correct operation.", "answerHTML": "<p>dependency<\/p>", "group": "36-41", "lecture": "2", "href": "lesson.html#practice-36-41", "answer": "dependency"}, {"id": "q-0979b7acee4d42", "type": "blank", "prompt": "A trust boundary exists between areas with different trust _______.", "answerHTML": "<p>assumptions<\/p>", "group": "36-41", "lecture": "2", "href": "lesson.html#practice-36-41", "answer": "assumptions"}, {"id": "q-327eabcfc37c32", "type": "blank", "prompt": "A trust boundary may involve data, commands, identity, or _______.", "answerHTML": "<p>control<\/p>", "group": "36-41", "lecture": "2", "href": "lesson.html#practice-36-41", "answer": "control"}, {"id": "q-a58f2762978a4d", "type": "short", "prompt": "Question: Is an asset always a physical object?", "answerHTML": "<p><strong>Answer:<\/strong> No.<\/p><p>الـAsset ممكن يكون بيانات، وظيفة، حساب مستخدم، أو حتى ثقة المستخدمين.<\/p>", "group": "42", "lecture": "2", "href": "lesson.html#slide-42", "context": ""}, {"id": "q-08d9298fa8b9ac", "type": "short", "prompt": "Q1. Identify one Device Asset.", "answerHTML": "<p><strong>Answer:<\/strong> Correct sensor operation.<\/p>", "group": "42", "lecture": "2", "href": "lesson.html#slide-42", "context": "A hospital uses connected patient sensors. The sensors collect measurements, send them to a remote service, and allow clinical staff to monitor patient conditions."}, {"id": "q-7d9b105d996791", "type": "short", "prompt": "Q2. Identify one Service Asset.", "answerHTML": "<p><strong>Answer:<\/strong> Patient telemetry.<\/p>", "group": "42", "lecture": "2", "href": "lesson.html#slide-42", "context": "A hospital uses connected patient sensors. The sensors collect measurements, send them to a remote service, and allow clinical staff to monitor patient conditions."}, {"id": "q-c3441722a65765", "type": "short", "prompt": "Q3. Identify one Operational Asset.", "answerHTML": "<p><strong>Answer:<\/strong> Service availability.<\/p>", "group": "42", "lecture": "2", "href": "lesson.html#slide-42", "context": "A hospital uses connected patient sensors. The sensors collect measurements, send them to a remote service, and allow clinical staff to monitor patient conditions."}, {"id": "q-83a27a14b5c932", "type": "short", "prompt": "Q4. Is user trust an asset?", "answerHTML": "<p><strong>Answer:<\/strong> Yes. It is an Operational Asset in the lecture's classification.<\/p>", "group": "42", "lecture": "2", "href": "lesson.html#slide-42", "context": "A hospital uses connected patient sensors. The sensors collect measurements, send them to a remote service, and allow clinical staff to monitor patient conditions."}, {"id": "q-79c266b9780290", "type": "short", "prompt": "Q1. Identify the Data Path.", "answerHTML": "<p><strong>Answer:<\/strong> Thermostat Sensor → Device → Cloud → Dashboard.<\/p>", "group": "43", "lecture": "2", "href": "lesson.html#slide-43", "context": "A thermostat measures room temperature and sends readings to a cloud dashboard. A user can adjust the target temperature using a mobile application."}, {"id": "q-8a3bd2690d1795", "type": "short", "prompt": "Q2. Identify the Control Path.", "answerHTML": "<p><strong>Answer:<\/strong> Mobile Application → Cloud → Thermostat.<\/p>", "group": "43", "lecture": "2", "href": "lesson.html#slide-43", "context": "A thermostat measures room temperature and sends readings to a cloud dashboard. A user can adjust the target temperature using a mobile application."}, {"id": "q-09fff2c2e051a3", "type": "short", "prompt": "Q3. Why must both paths be included in an attack-surface map?", "answerHTML": "<p><strong>Answer:<\/strong> Because data and commands may cross different interfaces and trust boundaries.<\/p>", "group": "43", "lecture": "2", "href": "lesson.html#slide-43", "context": "A thermostat measures room temperature and sends readings to a cloud dashboard. A user can adjust the target temperature using a mobile application."}, {"id": "q-ee06b9a30994d8", "type": "short", "prompt": "Question: Is every communication path automatically a trust boundary?", "answerHTML": "<p><strong>Answer:<\/strong> No.<\/p><p>لازم يكون في اختلاف في افتراضات الثقة بين المنطقتين.<\/p>", "group": "44", "lecture": "2", "href": "lesson.html#slide-44", "context": ""}, {"id": "q-7a3176fe81abd3", "type": "short", "prompt": "Q1. Identify a possible trust boundary.", "answerHTML": "<p><strong>Answer:<\/strong> Mobile Application ↔ Cloud Service.<\/p>", "group": "44", "lecture": "2", "href": "lesson.html#slide-44", "context": "A mobile application communicates with a remote cloud service, which sends commands to a smart lock."}, {"id": "q-bf5d5401bb9a12", "type": "short", "prompt": "Q2. Why is it a possible trust boundary?", "answerHTML": "<p><strong>Answer:<\/strong> Because the application and remote service may operate under different trust assumptions.<\/p>", "group": "44", "lecture": "2", "href": "lesson.html#slide-44", "context": "A mobile application communicates with a remote cloud service, which sends commands to a smart lock."}, {"id": "q-1c30ae0b2c5701", "type": "short", "prompt": "Q3. What is the Week 1 goal?", "answerHTML": "<p><strong>Answer:<\/strong> Identify where trust assumptions change, without analyzing detailed protection mechanisms.<\/p>", "group": "44", "lecture": "2", "href": "lesson.html#slide-44", "context": "A mobile application communicates with a remote cloud service, which sends commands to a smart lock."}, {"id": "q-76ec95247967a1", "type": "short", "prompt": "Q1. Who can physically reach the sensor?", "answerHTML": "<p><strong>Answer:<\/strong> Maintenance Staff.<\/p>", "group": "45", "lecture": "2", "href": "lesson.html#slide-45", "context": "An industrial sensor is installed in a factory. Maintenance staff can physically access it. The sensor sends measurements through a gateway to a remote dashboard."}, {"id": "q-91a7e90554a7a5", "type": "short", "prompt": "Q2. What data does it handle?", "answerHTML": "<p><strong>Answer:<\/strong> Sensor Measurements.<\/p>", "group": "45", "lecture": "2", "href": "lesson.html#slide-45", "context": "An industrial sensor is installed in a factory. Maintenance staff can physically access it. The sensor sends measurements through a gateway to a remote dashboard."}, {"id": "q-da277abf3444d7", "type": "short", "prompt": "Q3. Where does data travel?", "answerHTML": "<p><strong>Answer:<\/strong> Sensor → Gateway → Remote Dashboard.<\/p>", "group": "45", "lecture": "2", "href": "lesson.html#slide-45", "context": "An industrial sensor is installed in a factory. Maintenance staff can physically access it. The sensor sends measurements through a gateway to a remote dashboard."}, {"id": "q-86f6e919a31385", "type": "short", "prompt": "Q4. What other component may depend on the sensor?", "answerHTML": "<p><strong>Answer:<\/strong> The monitoring system may depend on the sensor's measurements.<\/p>", "group": "45", "lecture": "2", "href": "lesson.html#slide-45", "context": "An industrial sensor is installed in a factory. Maintenance staff can physically access it. The sensor sends measurements through a gateway to a remote dashboard."}, {"id": "q-ca1a3e5d7f9924", "type": "short", "prompt": "Q1. Identify two Assets.", "answerHTML": "<p><strong>Answer:<\/strong> Video Recordings and Correct Camera Operation.<\/p>", "group": "46", "lecture": "2", "href": "lesson.html#slide-46", "context": "A smart camera records video and sends it to a cloud service. The owner views recordings using a mobile application. An installer performs maintenance."}, {"id": "q-9c1c546c808951", "type": "short", "prompt": "Q2. Identify two Interfaces.", "answerHTML": "<p><strong>Answer:<\/strong> Network Interface and Mobile Application Interface.<\/p>", "group": "46", "lecture": "2", "href": "lesson.html#slide-46", "context": "A smart camera records video and sends it to a cloud service. The owner views recordings using a mobile application. An installer performs maintenance."}, {"id": "q-6c731ea6848139", "type": "short", "prompt": "Q3. Identify one Dependency.", "answerHTML": "<p><strong>Answer:<\/strong> Cloud Service for remote recording access.<\/p>", "group": "46", "lecture": "2", "href": "lesson.html#slide-46", "context": "A smart camera records video and sends it to a cloud service. The owner views recordings using a mobile application. An installer performs maintenance."}, {"id": "q-0b8c732a419dcd", "type": "short", "prompt": "Q4. Identify one Human Workflow.", "answerHTML": "<p><strong>Answer:<\/strong> Installation or Maintenance.<\/p>", "group": "46", "lecture": "2", "href": "lesson.html#slide-46", "context": "A smart camera records video and sends it to a cloud service. The owner views recordings using a mobile application. An installer performs maintenance."}, {"id": "q-88dc4c6a6cb40d", "type": "short", "prompt": "Q5. Identify a possible Trust Boundary.", "answerHTML": "<p><strong>Answer:<\/strong> Mobile Application ↔ Cloud Service, if trust assumptions differ.<\/p>", "group": "46", "lecture": "2", "href": "lesson.html#slide-46", "context": "A smart camera records video and sends it to a cloud service. The owner views recordings using a mobile application. An installer performs maintenance."}, {"id": "q-7808d8ac8b0a0e", "type": "short", "prompt": "Q1. Identify the Data Path.", "answerHTML": "<p><strong>Answer:<\/strong> Thermostat → Local Network → Remote Service → Mobile Application.<\/p>", "group": "47", "lecture": "2", "href": "lesson.html#slide-47", "context": "A smart thermostat collects temperature measurements and sends them to a remote service. A mobile application allows users to view readings and adjust heating settings."}, {"id": "q-c07204b4c43d6d", "type": "short", "prompt": "Q2. Identify the Control Path.", "answerHTML": "<p><strong>Answer:<\/strong> Mobile Application → Remote Service → Local Network → Thermostat.<\/p>", "group": "47", "lecture": "2", "href": "lesson.html#slide-47", "context": "A smart thermostat collects temperature measurements and sends them to a remote service. A mobile application allows users to view readings and adjust heating settings."}, {"id": "q-1065d975cfab0b", "type": "short", "prompt": "Q3. Identify three Assets.", "answerHTML": "<p><strong>Answer:<\/strong> Temperature Measurements, Correct Thermostat Operation, and Service Availability.<\/p>", "group": "47", "lecture": "2", "href": "lesson.html#slide-47", "context": "A smart thermostat collects temperature measurements and sends them to a remote service. A mobile application allows users to view readings and adjust heating settings."}, {"id": "q-b2c2a2479c5194", "type": "short", "prompt": "Q4. Identify two possible Trust Boundaries.", "answerHTML": "<p><strong>Answer:<\/strong> Local Network ↔ Remote Service, and Application ↔ Remote Service, where trust assumptions differ.<\/p>", "group": "47", "lecture": "2", "href": "lesson.html#slide-47", "context": "A smart thermostat collects temperature measurements and sends them to a remote service. A mobile application allows users to view readings and adjust heating settings."}, {"id": "q-7c0f8a2a821e3d", "type": "short", "prompt": "Q5. Why should we avoid naming specific attacks at this stage?", "answerHTML": "<p><strong>Answer:<\/strong> Because the Week 1 goal is to identify interfaces, dependencies, physical access points, and trust boundaries before analyzing detailed threats.<\/p>", "group": "47", "lecture": "2", "href": "lesson.html#slide-47", "context": "A smart thermostat collects temperature measurements and sends them to a remote service. A mobile application allows users to view readings and adjust heating settings."}, {"id": "q-a0bd8db5e554e9", "type": "mcq", "prompt": "Which of the following is a Device Asset?", "answerHTML": "<p>B. Local configuration<\/p><p>Local Configuration من Device Assets حسب تصنيف Slide 42.<\/p>", "group": "42-47", "lecture": "2", "href": "lesson.html#practice-42-47", "options": ["User trust", "Local configuration", "Availability of service", "Fleet manageability"], "correct": 1, "explanation": "Local Configuration من Device Assets حسب تصنيف Slide 42.", "persist": "lecture2-42-47-q1"}, {"id": "q-bc686b086301dc", "type": "mcq", "prompt": "Which is classified as a Service Asset?", "answerHTML": "<p>C. Telemetry<\/p><p>Telemetry موجودة تحت Service Assets.<\/p>", "group": "42-47", "lecture": "2", "href": "lesson.html#practice-42-47", "options": ["Physical actuation", "Correct physical behavior", "Telemetry", "User trust"], "correct": 2, "explanation": "Telemetry موجودة تحت Service Assets.", "persist": "lecture2-42-47-q2"}, {"id": "q-c36055a26622cc", "type": "mcq", "prompt": "Which is an Operational Asset?", "answerHTML": "<p>A. Fleet manageability<\/p><p>Fleet Manageability من Operational Assets.<\/p>", "group": "42-47", "lecture": "2", "href": "lesson.html#practice-42-47", "options": ["Fleet manageability", "Local identifiers", "Device memory", "Stored device configuration"], "correct": 0, "explanation": "Fleet Manageability من Operational Assets.", "persist": "lecture2-42-47-q3"}, {"id": "q-c0453ee76127bf", "type": "mcq", "prompt": "What should be included in an IoT data-and-control diagram?", "answerHTML": "<p>D. Both outward data flow and returning control commands<\/p><p>لازم نرسم Data Path وControl Path معًا.<\/p>", "group": "42-47", "lecture": "2", "href": "lesson.html#practice-42-47", "options": ["Only sensor readings", "Only cloud interfaces", "Only device hardware", "Both outward data flow and returning control commands"], "correct": 3, "explanation": "لازم نرسم Data Path وControl Path معًا.", "persist": "lecture2-42-47-q4"}, {"id": "q-81944691a576de", "type": "mcq", "prompt": "What does a trust boundary indicate?", "answerHTML": "<p>A. A change in trust assumptions<\/p><p>Trust Boundary بتشير لتغير افتراضات الثقة.<\/p>", "group": "42-47", "lecture": "2", "href": "lesson.html#practice-42-47", "options": ["A change in trust assumptions", "A guaranteed vulnerability", "Only a wireless connection", "A device identifier"], "correct": 0, "explanation": "Trust Boundary بتشير لتغير افتراضات الثقة.", "persist": "lecture2-42-47-q5"}, {"id": "q-f86b2185dc2286", "type": "mcq", "prompt": "Which is an example of a possible trust boundary?", "answerHTML": "<p>B. Application to cloud with different trust assumptions<\/p><p>Application ↔ Cloud ممكن يكون Trust Boundary عندما تختلف افتراضات الثقة.<\/p>", "group": "42-47", "lecture": "2", "href": "lesson.html#practice-42-47", "options": ["Two files in the same folder", "Application to cloud with different trust assumptions", "Two sensors with the same owner and trust context", "A temperature reading stored locally"], "correct": 1, "explanation": "Application ↔ Cloud ممكن يكون Trust Boundary عندما تختلف افتراضات الثقة.", "persist": "lecture2-42-47-q6"}, {"id": "q-9115056efea566", "type": "mcq", "prompt": "Which set contains the three questions for every component?", "answerHTML": "<p>C. Who, What, Where<\/p><p>Slide 45 منظمة حول Who, What, Where.<\/p>", "group": "42-47", "lecture": "2", "href": "lesson.html#practice-42-47", "options": ["When, Why, How", "If, Then, Else", "Who, What, Where", "Read, Write, Execute"], "correct": 2, "explanation": "Slide 45 منظمة حول Who, What, Where.", "persist": "lecture2-42-47-q7"}, {"id": "q-afb900d6c46e4d", "type": "mcq", "prompt": "Which question belongs under WHO?", "answerHTML": "<p>D. Who administers it?<\/p><p>Who administers it? من أسئلة WHO.<\/p>", "group": "42-47", "lecture": "2", "href": "lesson.html#practice-42-47", "options": ["What data does it handle?", "Where does trust change?", "What failure matters?", "Who administers it?"], "correct": 3, "explanation": "Who administers it? من أسئلة WHO.", "persist": "lecture2-42-47-q8"}, {"id": "q-24a15d7e632c95", "type": "mcq", "prompt": "Which component is explicitly included in the smart camera example?", "answerHTML": "<p>B. Remote storage service<\/p><p>Slide 46 بتذكر Remote Storage ضمن Service.<\/p>", "group": "42-47", "lecture": "2", "href": "lesson.html#practice-42-47", "options": ["Mandatory gateway", "Remote storage service", "Industrial robot", "Hospital controller"], "correct": 1, "explanation": "Slide 46 بتذكر Remote Storage ضمن Service.", "persist": "lecture2-42-47-q9"}, {"id": "q-e1ae94e3bcaa89", "type": "mcq", "prompt": "What is requested in the smart thermostat mini exercise?", "answerHTML": "<p>A. Identify three assets without naming attacks<\/p><p>المطلوب تحديد ثلاثة Assets بدون تسمية هجمات.<\/p>", "group": "42-47", "lecture": "2", "href": "lesson.html#practice-42-47", "options": ["Identify three assets without naming attacks", "Demonstrate firmware exploitation", "Calculate encryption key length", "List confirmed vulnerabilities"], "correct": 0, "explanation": "المطلوب تحديد ثلاثة Assets بدون تسمية هجمات.", "persist": "lecture2-42-47-q10"}, {"id": "q-b4b8a44741aca4", "type": "blank", "prompt": "User accounts and telemetry are examples of _______ Assets.", "answerHTML": "<p>Service<\/p>", "group": "42-47", "lecture": "2", "href": "lesson.html#practice-42-47", "answer": "Service"}, {"id": "q-7883d849bdc574", "type": "blank", "prompt": "Correct physical behavior is an _______ Asset.", "answerHTML": "<p>Operational<\/p>", "group": "42-47", "lecture": "2", "href": "lesson.html#practice-42-47", "answer": "Operational"}, {"id": "q-0412be3fc6ccb9", "type": "blank", "prompt": "Device operation and local configuration are _______ Assets.", "answerHTML": "<p>Device<\/p>", "group": "42-47", "lecture": "2", "href": "lesson.html#practice-42-47", "answer": "Device"}, {"id": "q-c6f1ef5417f24a", "type": "blank", "prompt": "A diagram should show both data and _______ paths.", "answerHTML": "<p>control<\/p>", "group": "42-47", "lecture": "2", "href": "lesson.html#practice-42-47", "answer": "control"}, {"id": "q-9eb81006646c5e", "type": "blank", "prompt": "A trust boundary marks a change in trust _______.", "answerHTML": "<p>assumptions<\/p>", "group": "42-47", "lecture": "2", "href": "lesson.html#practice-42-47", "answer": "assumptions"}, {"id": "q-673435f729afe1", "type": "blank", "prompt": "The three questions for every component are Who, What, and _______.", "answerHTML": "<p>Where<\/p>", "group": "42-47", "lecture": "2", "href": "lesson.html#practice-42-47", "answer": "Where"}, {"id": "q-0e641807c1c9f9", "type": "blank", "prompt": "Who _______ it? is one of the WHO questions.", "answerHTML": "<p>administers<\/p>", "group": "42-47", "lecture": "2", "href": "lesson.html#practice-42-47", "answer": "administers"}, {"id": "q-2f870e13711e27", "type": "blank", "prompt": "What _______ does it handle? is one of the WHAT questions.", "answerHTML": "<p>data<\/p>", "group": "42-47", "lecture": "2", "href": "lesson.html#practice-42-47", "answer": "data"}, {"id": "q-ae66d90f1e151a", "type": "blank", "prompt": "Where does _______ change? is one of the WHERE questions.", "answerHTML": "<p>trust<\/p>", "group": "42-47", "lecture": "2", "href": "lesson.html#practice-42-47", "answer": "trust"}, {"id": "q-8e5351dc71f151", "type": "blank", "prompt": "The smart camera example includes remote storage, device management, notifications, and _______ services.", "answerHTML": "<p>account<\/p>", "group": "42-47", "lecture": "2", "href": "lesson.html#practice-42-47", "answer": "account"}, {"id": "q-5f3a6cf46cb656", "type": "blank", "prompt": "The smart thermostat exercise asks students to identify three _______.", "answerHTML": "<p>assets<\/p>", "group": "42-47", "lecture": "2", "href": "lesson.html#practice-42-47", "answer": "assets"}, {"id": "q-b8beef691ef267", "type": "blank", "prompt": "Students should identify assets without naming _______.", "answerHTML": "<p>attacks<\/p>", "group": "42-47", "lecture": "2", "href": "lesson.html#practice-42-47", "answer": "attacks"}, {"id": "q-5ca956f697ea77", "type": "short", "prompt": "Q1. What continues if the cloud is removed?", "answerHTML": "<p>Answer: Local recording may continue.<\/p>", "group": "48", "lecture": "2", "href": "lesson.html#slide-48", "context": "A smart camera records video locally but uses a cloud service for remote viewing and notifications."}, {"id": "q-459644912cc24d", "type": "short", "prompt": "Q2. What may stop working?", "answerHTML": "<p>Answer: Remote viewing and cloud-based notifications.<\/p>", "group": "48", "lecture": "2", "href": "lesson.html#slide-48", "context": "A smart camera records video locally but uses a cloud service for remote viewing and notifications."}, {"id": "q-9e77dc8bf39935", "type": "short", "prompt": "Q3. What does this scenario demonstrate?", "answerHTML": "<p>Answer: Architecture and dependencies affect system functionality and security exposure.<\/p>", "group": "48", "lecture": "2", "href": "lesson.html#slide-48", "context": "A smart camera records video locally but uses a cloud service for remote viewing and notifications."}, {"id": "q-51615b3a3ec3d1", "type": "short", "prompt": "Q1. What should be recorded for each interface?", "answerHTML": "<p>Answer: Name, Location, Who Can Reach It, Purpose, and Trust Change.<\/p>", "group": "50", "lecture": "2", "href": "lesson.html#slide-50", "context": "A building has door sensors connected to a gateway. Administrators monitor the sensors using a cloud dashboard."}, {"id": "q-59bcd379029377", "type": "short", "prompt": "Q2. Why is the purpose field important?", "answerHTML": "<p>Answer: It explains why the interface exists and what function it enables.<\/p>", "group": "50", "lecture": "2", "href": "lesson.html#slide-50", "context": "A building has door sensors connected to a gateway. Administrators monitor the sensors using a cloud dashboard."}, {"id": "q-ca51d0a22c8849", "type": "short", "prompt": "Q3. What does Trust Change help identify?", "answerHTML": "<p>Answer: Whether information or control crosses into a differently managed area.<\/p>", "group": "50", "lecture": "2", "href": "lesson.html#slide-50", "context": "A building has door sensors connected to a gateway. Administrators monitor the sensors using a cloud dashboard."}, {"id": "q-532c5f3927ff45", "type": "short", "prompt": "Q1. Identify an internal exposure.", "answerHTML": "<p>Answer: Sensor ↔ Gateway.<\/p>", "group": "51", "lecture": "2", "href": "lesson.html#slide-51", "context": "A factory gateway communicates with several sensors over a local network. The gateway also communicates with a remote cloud service."}, {"id": "q-9c122d0486210e", "type": "short", "prompt": "Q2. Identify a possible external exposure.", "answerHTML": "<p>Answer: A remotely reachable Cloud Service Interface.<\/p>", "group": "51", "lecture": "2", "href": "lesson.html#slide-51", "context": "A factory gateway communicates with several sensors over a local network. The gateway also communicates with a remote cloud service."}, {"id": "q-db5664cf3d9ec9", "type": "short", "prompt": "Q3. Why must internal interfaces be mapped?", "answerHTML": "<p>Answer: Because compromise of one component may make other internal interfaces reachable.<\/p>", "group": "51", "lecture": "2", "href": "lesson.html#slide-51", "context": "A factory gateway communicates with several sensors over a local network. The gateway also communicates with a remote cloud service."}, {"id": "q-3b77a1505d73ac", "type": "short", "prompt": "Q1. What type of interface is described?", "answerHTML": "<p>Answer: Management / Maintenance Interface.<\/p>", "group": "52", "lecture": "2", "href": "lesson.html#slide-52", "context": "An installer uses a maintenance interface to configure building sensors. After installation, the interface remains available on the devices."}, {"id": "q-e5205796af4eea", "type": "short", "prompt": "Q2. Why does it deserve attention?", "answerHTML": "<p>Answer: It may provide powerful functions and remain present after deployment.<\/p>", "group": "52", "lecture": "2", "href": "lesson.html#slide-52", "context": "An installer uses a maintenance interface to configure building sensors. After installation, the interface remains available on the devices."}, {"id": "q-ca6af985da2bbf", "type": "short", "prompt": "Q3. What is the Week 1 goal?", "answerHTML": "<p>Answer: Identify the interface and include it in the attack-surface map.<\/p>", "group": "52", "lecture": "2", "href": "lesson.html#slide-52", "context": "An installer uses a maintenance interface to configure building sensors. After installation, the interface remains available on the devices."}, {"id": "q-31031e788b93e4", "type": "short", "prompt": "Q1. What is the essential local function?", "answerHTML": "<p>Answer: Collecting patient measurements.<\/p>", "group": "53", "lecture": "2", "href": "lesson.html#slide-53", "context": "A medical sensor measures patient data locally but depends on a remote service to display the readings to clinical staff."}, {"id": "q-d4d7ed144ecf6b", "type": "short", "prompt": "Q2. What function depends on the remote service?", "answerHTML": "<p>Answer: Displaying measurements to clinical staff remotely.<\/p>", "group": "53", "lecture": "2", "href": "lesson.html#slide-53", "context": "A medical sensor measures patient data locally but depends on a remote service to display the readings to clinical staff."}, {"id": "q-7f0e74ebe552a7", "type": "short", "prompt": "Q3. What happens if the remote service becomes unavailable?", "answerHTML": "<p>Answer: Local sensing may continue, but remote access to readings may be interrupted.<\/p>", "group": "53", "lecture": "2", "href": "lesson.html#slide-53", "context": "A medical sensor measures patient data locally but depends on a remote service to display the readings to clinical staff."}, {"id": "q-486879d3fc45cf", "type": "short", "prompt": "Q4. Why is dependency mapping important?", "answerHTML": "<p>Answer: It reveals hidden dependencies and supports availability and resilience analysis.<\/p>", "group": "53", "lecture": "2", "href": "lesson.html#slide-53", "context": "A medical sensor measures patient data locally but depends on a remote service to display the readings to clinical staff."}, {"id": "q-9130ee290a9d79", "type": "mcq", "prompt": "What determines which functions continue if the cloud is removed?", "answerHTML": "<p>B. The system architecture and dependencies<\/p><p>النتيجة بتعتمد على بنية النظام والاعتمادات.<\/p>", "group": "48-53", "lecture": "2", "href": "lesson.html#practice-48-53", "options": ["The number of users only", "The system architecture and dependencies", "The device color", "The size of the application"], "correct": 1, "explanation": "النتيجة بتعتمد على بنية النظام والاعتمادات.", "persist": "lecture2-48-53-q1"}, {"id": "q-2e7e4a4cabcbf6", "type": "mcq", "prompt": "What is the first step in the attack-surface mapping method?", "answerHTML": "<p>C. Draw the physical device and its purpose<\/p><p>الخطوة الأولى هي رسم الجهاز الفيزيائي وتحديد وظيفته.<\/p>", "group": "48-53", "lecture": "2", "href": "lesson.html#practice-48-53", "options": ["List vulnerabilities", "Draw trust boundaries", "Draw the physical device and its purpose", "Analyze encryption"], "correct": 2, "explanation": "الخطوة الأولى هي رسم الجهاز الفيزيائي وتحديد وظيفته.", "persist": "lecture2-48-53-q2"}, {"id": "q-a389240a21cba0", "type": "mcq", "prompt": "Which step involves drawing telemetry and command paths?", "answerHTML": "<p>D. Step 4<\/p><p>Step 4: Draw data and control paths.<\/p>", "group": "48-53", "lecture": "2", "href": "lesson.html#practice-48-53", "options": ["Step 1", "Step 2", "Step 3", "Step 4"], "correct": 3, "explanation": "Step 4: Draw data and control paths.", "persist": "lecture2-48-53-q3"}, {"id": "q-3a21f10dbebe0d", "type": "mcq", "prompt": "Which field is part of an attack-surface inventory?", "answerHTML": "<p>A. Who can reach it<\/p><p>Who Can Reach It من الحقول الخمسة الأساسية.<\/p>", "group": "48-53", "lecture": "2", "href": "lesson.html#practice-48-53", "options": ["Who can reach it", "Favorite device brand", "Purchase discount", "Screen resolution only"], "correct": 0, "explanation": "Who Can Reach It من الحقول الخمسة الأساسية.", "persist": "lecture2-48-53-q4"}, {"id": "q-69835550fadba8", "type": "mcq", "prompt": "What does the Trust Change field identify?", "answerHTML": "<p>B. Whether information or control crosses into a differently managed area<\/p><p>الحقل بحدد إذا في انتقال إلى منطقة مختلفة بالإدارة أو افتراضات الثقة.<\/p>", "group": "48-53", "lecture": "2", "href": "lesson.html#practice-48-53", "options": ["Device battery capacity", "Whether information or control crosses into a differently managed area", "Number of sensors", "Software purchase date"], "correct": 1, "explanation": "الحقل بحدد إذا في انتقال إلى منطقة مختلفة بالإدارة أو افتراضات الثقة.", "persist": "lecture2-48-53-q5"}, {"id": "q-b74680e5b97757", "type": "mcq", "prompt": "Which is an example of internal exposure?", "answerHTML": "<p>C. Device-to-Gateway communication<\/p><p>Device-to-Gateway مثال على تفاعل داخلي.<\/p>", "group": "48-53", "lecture": "2", "href": "lesson.html#practice-48-53", "options": ["A public web interface", "An external remote service", "Device-to-Gateway communication", "A product advertisement"], "correct": 2, "explanation": "Device-to-Gateway مثال على تفاعل داخلي.", "persist": "lecture2-48-53-q6"}, {"id": "q-38b9481a56d9f6", "type": "mcq", "prompt": "Which statement is correct about internal interfaces?", "answerHTML": "<p>D. They must still be included in attack-surface mapping<\/p><p>Internal مش معناها Trusted تلقائيًا.<\/p>", "group": "48-53", "lecture": "2", "href": "lesson.html#practice-48-53", "options": ["They are always secure", "They can be ignored", "They cannot be reached after a compromise", "They must still be included in attack-surface mapping"], "correct": 3, "explanation": "Internal مش معناها Trusted تلقائيًا.", "persist": "lecture2-48-53-q7"}, {"id": "q-b18e5969e88276", "type": "mcq", "prompt": "Which interface may provide more powerful functions than ordinary user interaction?", "answerHTML": "<p>A. Management Interface<\/p><p>Management Interfaces ممكن توفر وظائف إدارة وتشخيص وصيانة أوسع.<\/p>", "group": "48-53", "lecture": "2", "href": "lesson.html#practice-48-53", "options": ["Management Interface", "Temperature Sensor", "Physical Actuator", "Telemetry Record"], "correct": 0, "explanation": "Management Interfaces ممكن توفر وظائف إدارة وتشخيص وصيانة أوسع.", "persist": "lecture2-48-53-q8"}, {"id": "q-d50333dcb8ad1f", "type": "mcq", "prompt": "Which interface may remain present after installation?", "answerHTML": "<p>B. An installation or maintenance interface<\/p><p>بعض واجهات التركيب والصيانة بتظل موجودة بعد تشغيل النظام.<\/p>", "group": "48-53", "lecture": "2", "href": "lesson.html#practice-48-53", "options": ["A deleted cloud service", "An installation or maintenance interface", "A removed device", "A disconnected sensor only"], "correct": 1, "explanation": "بعض واجهات التركيب والصيانة بتظل موجودة بعد تشغيل النظام.", "persist": "lecture2-48-53-q9"}, {"id": "q-d2467c5f6ca080", "type": "mcq", "prompt": "What should dependency mapping distinguish?", "answerHTML": "<p>C. Essential operation and convenience features<\/p><p>التمييز بين Essential Operation وConvenience Features.<\/p>", "group": "48-53", "lecture": "2", "href": "lesson.html#practice-48-53", "options": ["Wireless and wired colors", "Old and new logos", "Essential operation and convenience features", "Only device manufacturers"], "correct": 2, "explanation": "التمييز بين Essential Operation وConvenience Features.", "persist": "lecture2-48-53-q10"}, {"id": "q-dc292e927edd4d", "type": "mcq", "prompt": "Which dependency may be required for remote viewing?", "answerHTML": "<p>A. Cloud Service<\/p><p>الخدمة السحابية ممكن تكون مطلوبة للوصول عن بُعد، حسب تصميم النظام.<\/p>", "group": "48-53", "lecture": "2", "href": "lesson.html#practice-48-53", "options": ["Cloud Service", "Device packaging", "Screen wallpaper", "Physical label"], "correct": 0, "explanation": "الخدمة السحابية ممكن تكون مطلوبة للوصول عن بُعد، حسب تصميم النظام.", "persist": "lecture2-48-53-q11"}, {"id": "q-d979f23691fa12", "type": "mcq", "prompt": "What is the main Week 1 goal when examining management interfaces?", "answerHTML": "<p>D. Identify their existence and include them in the map<\/p><p>Week 1 بيركز على تحديد الواجهات، مش استغلالها.<\/p>", "group": "48-53", "lecture": "2", "href": "lesson.html#practice-48-53", "options": ["Exploit them", "Bypass authentication", "Remove all interfaces", "Identify their existence and include them in the map"], "correct": 3, "explanation": "Week 1 بيركز على تحديد الواجهات، مش استغلالها.", "persist": "lecture2-48-53-q12"}, {"id": "q-2433505fe760b2", "type": "blank", "prompt": "Removing the cloud demonstrates why architecture and _______ affect security exposure.", "answerHTML": "<p>dependencies<\/p>", "group": "48-53", "lecture": "2", "href": "lesson.html#practice-48-53", "answer": "dependencies"}, {"id": "q-31a7c91ba1524b", "type": "blank", "prompt": "The first mapping step is to draw the physical device and its _______.", "answerHTML": "<p>purpose<\/p>", "group": "48-53", "lecture": "2", "href": "lesson.html#practice-48-53", "answer": "purpose"}, {"id": "q-94cdb8eb490bf9", "type": "blank", "prompt": "The fourth mapping step is to draw data and _______ paths.", "answerHTML": "<p>control<\/p>", "group": "48-53", "lecture": "2", "href": "lesson.html#practice-48-53", "answer": "control"}, {"id": "q-d0481dd45989c7", "type": "blank", "prompt": "The fifth mapping step includes interfaces, dependencies, physical access points, and trust _______.", "answerHTML": "<p>boundaries<\/p>", "group": "48-53", "lecture": "2", "href": "lesson.html#practice-48-53", "answer": "boundaries"}, {"id": "q-de2deb6d636c09", "type": "blank", "prompt": "An attack-surface inventory should record the interface name, location, who can reach it, purpose, and trust _______.", "answerHTML": "<p>change<\/p>", "group": "48-53", "lecture": "2", "href": "lesson.html#practice-48-53", "answer": "change"}, {"id": "q-202e54a8806f54", "type": "blank", "prompt": "External exposure is reachable from _______ the immediate device or trusted environment.", "answerHTML": "<p>outside<\/p>", "group": "48-53", "lecture": "2", "href": "lesson.html#practice-48-53", "answer": "outside"}, {"id": "q-9731b0f10fe47c", "type": "blank", "prompt": "Internal exposure exists _______ components inside the ecosystem.", "answerHTML": "<p>between<\/p>", "group": "48-53", "lecture": "2", "href": "lesson.html#practice-48-53", "answer": "between"}, {"id": "q-9ee98b777ea1c8", "type": "blank", "prompt": "Internal does not automatically mean _______.", "answerHTML": "<p>trusted<\/p>", "group": "48-53", "lecture": "2", "href": "lesson.html#practice-48-53", "answer": "trusted"}, {"id": "q-94abb390b621b2", "type": "blank", "prompt": "Management interfaces may provide more _______ functions than ordinary user interfaces.", "answerHTML": "<p>powerful<\/p>", "group": "48-53", "lecture": "2", "href": "lesson.html#practice-48-53", "answer": "powerful"}, {"id": "q-b0b400726a1ab9", "type": "blank", "prompt": "Some maintenance interfaces remain present after _______.", "answerHTML": "<p>deployment<\/p>", "group": "48-53", "lecture": "2", "href": "lesson.html#practice-48-53", "answer": "deployment"}, {"id": "q-f500d6233ddd5f", "type": "blank", "prompt": "Dependency mapping separates essential operation from _______ features.", "answerHTML": "<p>convenience<\/p>", "group": "48-53", "lecture": "2", "href": "lesson.html#practice-48-53", "answer": "convenience"}, {"id": "q-6b073c52e7e3ed", "type": "blank", "prompt": "Dependency mapping supports later availability and _______ analysis.", "answerHTML": "<p>resilience<\/p>", "group": "48-53", "lecture": "2", "href": "lesson.html#practice-48-53", "answer": "resilience"}, {"id": "q-34c7f34f1d17a8", "type": "short", "prompt": "Q1. Identify the four trust boundaries.", "answerHTML": "<p><strong>Model Answer:<\/strong><\/p>", "group": "54", "lecture": "2", "href": "lesson.html#slide-54", "context": "A user presses the Unlock button in a mobile application. The application sends the request to a remote service. The remote service forwards a command to the smart lock, which activates its physical locking mechanism."}, {"id": "q-45bb52af20c68f", "type": "short", "prompt": "Q2. Which boundary connects the digital and physical worlds?", "answerHTML": "<p><strong>Answer:<\/strong> Boundary 4.<\/p>", "group": "54", "lecture": "2", "href": "lesson.html#slide-54", "context": "A user presses the Unlock button in a mobile application. The application sends the request to a remote service. The remote service forwards a command to the smart lock, which activates its physical locking mechanism."}, {"id": "q-1abcfef72100e6", "type": "short", "prompt": "Q3. What should be identified at each boundary?", "answerHTML": "<p><strong>Answer:<\/strong> The identity, data, or command crossing the boundary.<\/p>", "group": "54", "lecture": "2", "href": "lesson.html#slide-54", "context": "A user presses the Unlock button in a mobile application. The application sends the request to a remote service. The remote service forwards a command to the smart lock, which activates its physical locking mechanism."}, {"id": "q-fc8e9a96a3f6ba", "type": "short", "prompt": "Q4. Should you explain encryption or authentication mechanisms in this exercise?", "answerHTML": "<p><strong>Answer:<\/strong> No. The Week 1 objective is to identify trust boundaries, not detailed security mechanisms.<\/p>", "group": "54", "lecture": "2", "href": "lesson.html#slide-54", "context": "A user presses the Unlock button in a mobile application. The application sends the request to a remote service. The remote service forwards a command to the smart lock, which activates its physical locking mechanism."}, {"id": "q-4d2bec95d25baf", "type": "short", "prompt": "Q1. Identify three mistakes.", "answerHTML": "<p><strong>Answer:<\/strong><\/p>", "group": "55", "lecture": "2", "href": "lesson.html#slide-55", "context": "A student maps a smart camera system by listing only open network ports and cloud storage. The student ignores installers and the mobile application, and assumes all local interfaces are trusted."}, {"id": "q-93561c86e2c8e8", "type": "short", "prompt": "Q2. What else should the student check?", "answerHTML": "<p><strong>Answer:<\/strong> Data and control paths, physical interfaces, dependencies, and trust boundaries.<\/p>", "group": "55", "lecture": "2", "href": "lesson.html#slide-55", "context": "A student maps a smart camera system by listing only open network ports and cloud storage. The student ignores installers and the mobile application, and assumes all local interfaces are trusted."}, {"id": "q-4bbe9bc337c02a", "type": "short", "prompt": "Q1. Which system illustrates a larger deployment scale?", "answerHTML": "<p><strong>Answer:<\/strong> System B.<\/p>", "group": "56", "lecture": "2", "href": "lesson.html#slide-56", "context": ""}, {"id": "q-e610e6dc01c0f1", "type": "short", "prompt": "Q2. Which system has a shared gateway dependency?", "answerHTML": "<p><strong>Answer:<\/strong> System B.<\/p>", "group": "56", "lecture": "2", "href": "lesson.html#slide-56", "context": ""}, {"id": "q-17bc9c22344512", "type": "short", "prompt": "Q3. Can we conclude that System B is less secure?", "answerHTML": "<p><strong>Answer:<\/strong> No. More devices and dependencies do not automatically prove insecurity.<\/p>", "group": "56", "lecture": "2", "href": "lesson.html#slide-56", "context": ""}, {"id": "q-ca11d1b5f1a33c", "type": "short", "prompt": "Q4. What additional information is needed?", "answerHTML": "<p><strong>Answer:<\/strong> Interface reachability, physical accessibility, users, communication paths, trust boundaries, and system architecture.<\/p>", "group": "56", "lecture": "2", "href": "lesson.html#slide-56", "context": ""}, {"id": "q-a5fc35d29b970b", "type": "mcq", "prompt": "Which is the first trust boundary in the smart lock example?", "answerHTML": "<p>B. Physical User ↔ Mobile Application<\/p><p>Boundary 1 هي Physical User ↔ Mobile Application.<\/p>", "group": "54-58", "lecture": "2", "href": "lesson.html#practice-54-58", "options": ["Gateway ↔ Cloud", "Physical User ↔ Mobile Application", "Digital Command ↔ Locking Mechanism", "Device ↔ Database"], "correct": 1, "explanation": "Boundary 1 هي Physical User ↔ Mobile Application.", "persist": "lecture2-54-58-q1"}, {"id": "q-265ad59b9a694e", "type": "mcq", "prompt": "Which boundary connects a digital command to physical locking behavior?", "answerHTML": "<p>D. Boundary 4<\/p><p>Boundary 4 تربط Digital Command مع Physical Locking Mechanism.<\/p>", "group": "54-58", "lecture": "2", "href": "lesson.html#practice-54-58", "options": ["Boundary 1", "Boundary 2", "Boundary 3", "Boundary 4"], "correct": 3, "explanation": "Boundary 4 تربط Digital Command مع Physical Locking Mechanism.", "persist": "lecture2-54-58-q2"}, {"id": "q-14e7ca22c8d984", "type": "mcq", "prompt": "What should be identified at each trust boundary during Week 1?", "answerHTML": "<p>A. Identity, data, or commands crossing it<\/p><p>المطلوب تحديد شو بعبر الحد: Identity أو Data أو Command، مش طريقة حمايته.<\/p>", "group": "54-58", "lecture": "2", "href": "lesson.html#practice-54-58", "options": ["Identity, data, or commands crossing it", "Exact encryption algorithms", "Known exploits", "Password-cracking techniques"], "correct": 0, "explanation": "المطلوب تحديد شو بعبر الحد: Identity أو Data أو Command، مش طريقة حمايته.", "persist": "lecture2-54-58-q3"}, {"id": "q-a93b6334bf7dc5", "type": "mcq", "prompt": "Which is a common attack-surface mapping mistake?", "answerHTML": "<p>C. Looking only for open network ports<\/p><p>التركيز فقط على Open Ports وإهمال باقي الواجهات خطأ.<\/p>", "group": "54-58", "lecture": "2", "href": "lesson.html#practice-54-58", "options": ["Including human roles", "Mapping both data and control paths", "Looking only for open network ports", "Documenting dependencies"], "correct": 2, "explanation": "التركيز فقط على Open Ports وإهمال باقي الواجهات خطأ.", "persist": "lecture2-54-58-q4"}, {"id": "q-03bf67e26b3327", "type": "mcq", "prompt": "Why is drawing only the data path insufficient?", "answerHTML": "<p>B. It may omit control commands returning to devices<\/p><p>لازم نرسم Data Path وControl Path.<\/p>", "group": "54-58", "lecture": "2", "href": "lesson.html#practice-54-58", "options": ["Data paths are always insecure", "It may omit control commands returning to devices", "All IoT devices have no sensors", "Applications never send commands"], "correct": 1, "explanation": "لازم نرسم Data Path وControl Path.", "persist": "lecture2-54-58-q5"}, {"id": "q-7f3832b9073115", "type": "mcq", "prompt": "Which statement about internal network components is correct?", "answerHTML": "<p>D. Their trust must not be assumed solely from being internal<\/p><p>Internal لا تعني Trusted تلقائيًا.<\/p>", "group": "54-58", "lecture": "2", "href": "lesson.html#practice-54-58", "options": ["They are always trusted", "They never need to be mapped", "They cannot be accessed physically", "Their trust must not be assumed solely from being internal"], "correct": 3, "explanation": "Internal لا تعني Trusted تلقائيًا.", "persist": "lecture2-54-58-q6"}, {"id": "q-157aef4c63830f", "type": "mcq", "prompt": "Which factor is relevant when comparing the two IoT systems?", "answerHTML": "<p>A. Physical accessibility<\/p><p>المقارنة بتشمل Physical Accessibility وNumber of Devices وUsers وDependencies وFailure Consequences.<\/p>", "group": "54-58", "lecture": "2", "href": "lesson.html#practice-54-58", "options": ["Physical accessibility", "Brand logo color", "Product packaging design", "Font size in the application"], "correct": 0, "explanation": "المقارنة بتشمل Physical Accessibility وNumber of Devices وUsers وDependencies وFailure Consequences.", "persist": "lecture2-54-58-q7"}, {"id": "q-991bacafb86183", "type": "mcq", "prompt": "Can the larger attack surface be determined only by counting interfaces?", "answerHTML": "<p>C. No, architecture and exposure context also matter<\/p><p>عدد الواجهات لحاله مش كافي للحكم على Attack Surface.<\/p>", "group": "54-58", "lecture": "2", "href": "lesson.html#practice-54-58", "options": ["Yes, always", "Yes, only for home IoT", "No, architecture and exposure context also matter", "Only when the system uses BLE"], "correct": 2, "explanation": "عدد الواجهات لحاله مش كافي للحكم على Attack Surface.", "persist": "lecture2-54-58-q8"}, {"id": "q-338e9c3d09769a", "type": "mcq", "prompt": "How many components must be labeled in the Week 1 exit exercise?", "answerHTML": "<p>B. At least 5<\/p><p>المطلوب At least five components.<\/p>", "group": "54-58", "lecture": "2", "href": "lesson.html#practice-54-58", "options": ["At least 3", "At least 5", "Exactly 7", "At least 10"], "correct": 1, "explanation": "المطلوب At least five components.", "persist": "lecture2-54-58-q9"}, {"id": "q-f3f79943eb5253", "type": "mcq", "prompt": "How many communication or interaction paths are required in the exit exercise?", "answerHTML": "<p>A. At least 4<\/p><p>المطلوب At least four paths.<\/p>", "group": "54-58", "lecture": "2", "href": "lesson.html#practice-54-58", "options": ["At least 4", "Exactly 2", "At least 8", "Only 1"], "correct": 0, "explanation": "المطلوب At least four paths.", "persist": "lecture2-54-58-q10"}, {"id": "q-ef267e72b1f6f8", "type": "mcq", "prompt": "What is the minimum number of trust boundaries required?", "answerHTML": "<p>D. 3<\/p><p>المطلوب At least three trust boundaries.<\/p>", "group": "54-58", "lecture": "2", "href": "lesson.html#practice-54-58", "options": ["1", "2", "4", "3"], "correct": 3, "explanation": "المطلوب At least three trust boundaries.", "persist": "lecture2-54-58-q11"}, {"id": "q-06aee0b594b8d1", "type": "mcq", "prompt": "What is the minimum number of physical access points required?", "answerHTML": "<p>B. 2<\/p><p>المطلوب At least two physical access points.<\/p>", "group": "54-58", "lecture": "2", "href": "lesson.html#practice-54-58", "options": ["1", "2", "3", "5"], "correct": 1, "explanation": "المطلوب At least two physical access points.", "persist": "lecture2-54-58-q12"}, {"id": "q-b524bf45c5da56", "type": "mcq", "prompt": "Which topic belongs to Week 2 preparation?", "answerHTML": "<p>C. Authentication and Authorization<\/p><p>Week 2 بتتناول Device Identity وAuthentication وAuthorization وAccess Control وغيرها.<\/p>", "group": "54-58", "lecture": "2", "href": "lesson.html#practice-54-58", "options": ["Only device packaging", "Only sensor calibration", "Authentication and Authorization", "Only hardware manufacturing"], "correct": 2, "explanation": "Week 2 بتتناول Device Identity وAuthentication وAuthorization وAccess Control وغيرها.", "persist": "lecture2-54-58-q13"}, {"id": "q-0e136ecbf08c0a", "type": "blank", "prompt": "Boundary 1 in the smart lock example is physical user ↔ mobile _______.", "answerHTML": "<p>application<\/p>", "group": "54-58", "lecture": "2", "href": "lesson.html#practice-54-58", "answer": "application"}, {"id": "q-3bf41267736759", "type": "blank", "prompt": "Boundary 2 is application ↔ remote _______.", "answerHTML": "<p>service<\/p>", "group": "54-58", "lecture": "2", "href": "lesson.html#practice-54-58", "answer": "service"}, {"id": "q-794a5603bb8ed0", "type": "blank", "prompt": "Boundary 3 is remote service ↔ device or _______.", "answerHTML": "<p>gateway<\/p>", "group": "54-58", "lecture": "2", "href": "lesson.html#practice-54-58", "answer": "gateway"}, {"id": "q-5776b636738982", "type": "blank", "prompt": "Boundary 4 is digital command ↔ physical locking _______.", "answerHTML": "<p>mechanism<\/p>", "group": "54-58", "lecture": "2", "href": "lesson.html#practice-54-58", "answer": "mechanism"}, {"id": "q-e5a387dcf8e6b4", "type": "blank", "prompt": "At each trust boundary, identify what identity, data, or _______ is crossing.", "answerHTML": "<p>command<\/p>", "group": "54-58", "lecture": "2", "href": "lesson.html#practice-54-58", "answer": "command"}, {"id": "q-3c9eebaff9c30c", "type": "blank", "prompt": "A common mapping mistake is looking only for open network _______.", "answerHTML": "<p>ports<\/p>", "group": "54-58", "lecture": "2", "href": "lesson.html#practice-54-58", "answer": "ports"}, {"id": "q-2fbcd4eeb652a9", "type": "blank", "prompt": "A map must include both data flow and _______ commands.", "answerHTML": "<p>control<\/p>", "group": "54-58", "lecture": "2", "href": "lesson.html#practice-54-58", "answer": "control"}, {"id": "q-fa8ece17000ecc", "type": "blank", "prompt": "Being inside the local network does not automatically make a component _______.", "answerHTML": "<p>trusted<\/p>", "group": "54-58", "lecture": "2", "href": "lesson.html#practice-54-58", "answer": "trusted"}, {"id": "q-49e8192de41a33", "type": "blank", "prompt": "The comparison workshop includes physical accessibility, users, dependencies, and consequences of _______.", "answerHTML": "<p>failure<\/p>", "group": "54-58", "lecture": "2", "href": "lesson.html#practice-54-58", "answer": "failure"}, {"id": "q-18d7c5676d5bbf", "type": "blank", "prompt": "The exit exercise requires at least _______ components.", "answerHTML": "<p>five<\/p>", "group": "54-58", "lecture": "2", "href": "lesson.html#practice-54-58", "answer": "five"}, {"id": "q-0e206bdf3af038", "type": "blank", "prompt": "The exit exercise requires at least _______ communication or interaction paths.", "answerHTML": "<p>four<\/p>", "group": "54-58", "lecture": "2", "href": "lesson.html#practice-54-58", "answer": "four"}, {"id": "q-e92b3fcd3daaa2", "type": "blank", "prompt": "The exit exercise requires at least _______ trust boundaries.", "answerHTML": "<p>three<\/p>", "group": "54-58", "lecture": "2", "href": "lesson.html#practice-54-58", "answer": "three"}, {"id": "q-97a7e438dc032d", "type": "blank", "prompt": "The exit exercise requires at least _______ physical access points.", "answerHTML": "<p>two<\/p>", "group": "54-58", "lecture": "2", "href": "lesson.html#practice-54-58", "answer": "two"}, {"id": "q-544ddb13291494", "type": "blank", "prompt": "Week 2 introduces device identity, authentication, _______ and access control.", "answerHTML": "<p>authorization<\/p>", "group": "54-58", "lecture": "2", "href": "lesson.html#practice-54-58", "answer": "authorization"}, {"id": "q-93ed5fff5d2fe3", "type": "case", "prompt": "Smart Hospital Monitoring System", "answerHTML": "<ol dir=\"ltr\" lang=\"en\"><li>Physical Device, Device Software, Connectivity, Gateway / Edge, Cloud Service, and User Application with human interaction.<\/li><li>The sensors.<\/li><li>Because they have limited battery power.<\/li><li>It connects the sensors to the cloud service and forwards their measurements.<\/li><li>Cloud-dependent storage, access, or remote management may become unavailable. Local functions depend on the design.<\/li><li>The environment and dependencies may change while the devices remain deployed; maintainability and support matter.<\/li><li>Their actions affect access, configuration, and operation.<\/li><\/ol>", "group": "6-11", "lecture": "1", "href": "lesson.html#practice-6-11", "context": "A hospital uses multiple connected patient sensors to collect measurements. The sensors send their data through a local gateway to a cloud service. Medical staff use a web application to view the measurements. Some sensors have limited battery power, and the hospital has used the same devices for several years.", "questionsHTML": "<ol dir=\"ltr\"><li>Identify the six ecosystem components involved in the system.<\/li><li>Which component collects the patient measurements?<\/li><li>Why might the sensors prioritize low power?<\/li><li>What is the role of the gateway?<\/li><li>What happens if the cloud service becomes unavailable?<\/li><li>Why is the long deployment lifetime important?<\/li><li>Why should medical staff be considered part of the system boundary?<\/li><\/ol>"}, {"id": "q-90b0808930088d", "type": "case", "prompt": "Smart Factory", "answerHTML": "<ol dir=\"ltr\" lang=\"en\"><li>Scale, Heterogeneity, Constraints, and Long Lifetime.<\/li><li>The same mistake or configuration issue may affect thousands of devices.<\/li><li>Different vendors and platforms may require different management and update capabilities.<\/li><li>Devices may remain deployed while software support ends and dependencies or security assumptions become outdated.<\/li><\/ol>", "group": "12-17", "lecture": "1", "href": "lesson.html#practice-12-17", "context": "A factory operates 5,000 connected sensors from different manufacturers. Some sensors have limited memory and battery power. The devices have been installed for many years, and some no longer receive software support.", "questionsHTML": "<ol dir=\"ltr\"><li>Identify four IoT security challenges in this scenario.<\/li><li>Explain how scale affects security.<\/li><li>Why is heterogeneity important?<\/li><li>What does long lifetime imply?<\/li><\/ol>"}, {"id": "q-de352c4994a214", "type": "case", "prompt": "Smart Building Control", "answerHTML": "<ol dir=\"ltr\" lang=\"en\"><li>Because computation is tightly integrated with physical processes and feedback.<\/li><li>Sensing.<\/li><li>Actuation.<\/li><li>No. CPS classification is explained by the interaction between computation, physical processes, and feedback.<\/li><\/ol>", "group": "12-17", "lecture": "1", "href": "lesson.html#practice-12-17", "context": "A smart building system continuously measures indoor temperature and automatically adjusts the cooling system using sensor feedback. The system also sends measurements to a cloud dashboard.", "questionsHTML": "<ol dir=\"ltr\"><li>Why can this system be considered a CPS?<\/li><li>Which capability allows the system to measure temperature?<\/li><li>Which capability allows it to adjust cooling?<\/li><li>Does the presence of cloud connectivity alone explain the CPS classification?<\/li><\/ol>"}, {"id": "q-317c8bfc50ed23", "type": "case", "prompt": "Smart Lock Cloud Failure", "answerHTML": "<ol dir=\"ltr\" lang=\"en\"><li>Dependencies.<\/li><li>Cloud Service.<\/li><li>No. The lock may continue its local operation while cloud-dependent remote control becomes unavailable.<\/li><\/ol>", "group": "12-17", "lecture": "1", "href": "lesson.html#practice-12-17", "context": "A smart lock operates locally but relies on a cloud service for remote control. When the cloud becomes unavailable, users can no longer control the lock through the mobile application.", "questionsHTML": "<ol dir=\"ltr\"><li>Which IoT security challenge is illustrated?<\/li><li>What is the external dependency?<\/li><li>Does the cloud failure necessarily mean that the physical lock has stopped operating?<\/li><\/ol>"}, {"id": "q-ccf32114a20547", "type": "case", "prompt": "Smart Building Security Responsibilities", "answerHTML": "<ol dir=\"ltr\"><li>Enterprise / Building IoT.<\/li><li>Device Manufacturer.<\/li><li>Service Provider.<\/li><li>Installer / Organization.<\/li><li>Security gaps may appear between the responsible parties.<\/li><\/ol>", "group": "18-23", "lecture": "1", "href": "lesson.html#practice-18-23", "context": "A company installs smart access-control devices throughout its office building. The manufacturer provides the hardware and embedded software. A service provider manages the remote accounts. An installation team configures the devices and network, while employees operate the system daily.", "questionsHTML": "<ol dir=\"ltr\"><li>Identify the IoT category.<\/li><li>Who is responsible for hardware and embedded software?<\/li><li>Who manages account-related backend services?<\/li><li>Who handles deployment and configuration?<\/li><li>What problem may arise if responsibilities are unclear?<\/li><\/ol>", "answerOrigin": "source"}, {"id": "q-fd07eb73796eed", "type": "case", "prompt": "Smart Camera Analysis", "answerHTML": "<ol dir=\"ltr\"><li>Video monitoring.<\/li><li>Video recordings.<\/li><li>Remote service and network connection.<\/li><li>Physical Exposure.<\/li><li>Because the camera&#x27;s operation and security also depend on communication, remote storage, applications, and human interaction.<\/li><\/ol>", "group": "18-23", "lecture": "1", "href": "lesson.html#practice-18-23", "context": "A smart camera collects video, stores recordings through a remote service, and allows users to view the video through a mobile application. The camera is installed in a publicly accessible area.", "questionsHTML": "<ol dir=\"ltr\"><li>What service does the camera support?<\/li><li>What type of data does it collect?<\/li><li>Identify two dependencies.<\/li><li>What physical security concern exists?<\/li><li>Why is analyzing only the camera hardware insufficient?<\/li><\/ol>", "answerOrigin": "source"}, {"id": "q-6c865697aff9f0", "type": "case", "prompt": "Consumer vs. Industrial IoT", "answerHTML": "<ol dir=\"ltr\"><li>System A: Consumer IoT. System B: Industrial / Infrastructure IoT.<\/li><li>System B.<\/li><li>Because the category affects the environment, ownership model, expected lifetime, and consequences of failure.<\/li><\/ol>", "group": "18-23", "lecture": "1", "href": "lesson.html#practice-18-23", "context": "System A is a smart speaker used by a family at home. System B is a connected sensor used to monitor a critical industrial process.", "questionsHTML": "<ol dir=\"ltr\"><li>Classify System A and System B.<\/li><li>Which system is more directly associated with industrial operational consequences?<\/li><li>Why does the IoT category matter for security analysis?<\/li><\/ol>", "answerOrigin": "source"}, {"id": "q-58ac2b246de976", "type": "case", "prompt": "Smart Hospital System", "answerHTML": "<ol dir=\"ltr\"><li>Physical Layer: Patient Sensors. Local Layer: Gateways. Remote Layer: Monitoring Service and Dashboard. Human Layer: Clinical Staff.<\/li><li>Patient Sensors → Local Gateways → Remote Monitoring Service → Web Dashboard.<\/li><li>Scale, Dependencies, and Long Lifetime.<\/li><li>A repeated design or configuration mistake may affect thousands of devices.<\/li><li>Devices may outlive software support, and their dependencies or security assumptions may become outdated.<\/li><li>Incorrect data may mislead clinical staff, while service interruption may prevent access to patient measurements. Both can be important depending on clinical use.<\/li><li>No. The scenario describes measurement collection and reporting, not physical actuation.<\/li><\/ol>", "group": "24-29", "lecture": "1", "href": "lesson.html#practice-24-29", "context": "A hospital operates 2,000 connected patient sensors across several buildings. The sensors collect measurements and send them through local gateways to a remote monitoring service. Clinical staff use a web dashboard to view the data. Some sensors have been installed for many years, and several software dependencies are no longer supported.", "questionsHTML": "<ol dir=\"ltr\"><li>Identify the physical, local, remote, and human layers.<\/li><li>Describe the telemetry path.<\/li><li>Identify three security challenges.<\/li><li>Explain why scale changes the security problem.<\/li><li>Why does long lifetime matter?<\/li><li>Compare the potential impact of incorrect data and service interruption.<\/li><li>Can we conclude that the sensors perform physical actuation?<\/li><\/ol>", "answerOrigin": "source"}, {"id": "q-dd586e06232218", "type": "case", "prompt": "Smart Factory Monitoring", "answerHTML": "<ol dir=\"ltr\"><li>Firmware, Radio / Network, Gateway / Edge, Cloud / API, and Application / Human.<\/li><li>The local gateway.<\/li><li>Sensor measurements or correct sensor operation.<\/li><li>Wireless communication interface or web application interface.<\/li><li>Gateway ↔ Cloud Service, if they operate under different trust assumptions.<\/li><\/ol>", "group": "36-41", "lecture": "2", "href": "lesson.html#practice-36-41", "context": "A factory operates 300 connected sensors. Each sensor contains embedded firmware and communicates wirelessly with a local gateway. The gateway forwards measurements to a cloud service, where administrators monitor the system through a web application.", "questionsHTML": "<ol dir=\"ltr\"><li>Identify five attack-surface areas.<\/li><li>What is the shared dependency?<\/li><li>Identify one asset.<\/li><li>Identify one interface.<\/li><li>Identify one possible trust boundary.<\/li><\/ol>", "answerOrigin": "source"}, {"id": "q-7167f6afcfca32", "type": "case", "prompt": "Smart Camera Remote Access", "answerHTML": "<ol dir=\"ltr\"><li>Application / Human Surface.<\/li><li>Cloud / API Surface.<\/li><li>Video recordings.<\/li><li>The remote service for remote access to recordings.<\/li><li>Mobile Application ↔ Remote Service, if their trust assumptions differ.<\/li><\/ol>", "group": "36-41", "lecture": "2", "href": "lesson.html#practice-36-41", "context": "A smart camera stores recordings in a remote service. Users access the recordings through a mobile application. The application also allows account recovery and sharing access with family members.", "questionsHTML": "<ol dir=\"ltr\"><li>Which attack-surface area includes account recovery?<\/li><li>Which area includes remote recording storage?<\/li><li>Identify one asset.<\/li><li>Identify one dependency.<\/li><li>Identify a possible trust boundary.<\/li><\/ol>", "answerOrigin": "study"}, {"id": "q-ce53bce2051a91", "type": "case", "prompt": "Connected Medical Sensor", "answerHTML": "<ol dir=\"ltr\"><li>Patient measurements or correct sensor operation.<\/li><li>The sensor network interface.<\/li><li>The remote service for displaying readings to clinical staff.<\/li><li>Local Network ↔ Remote Service, if their trust assumptions differ.<\/li><li>An interface is a point of communication or access; a dependency is another component or service required for correct operation.<\/li><\/ol>", "group": "36-41", "lecture": "2", "href": "lesson.html#practice-36-41", "context": "A hospital uses connected medical sensors to collect patient measurements. The sensors communicate through a local network and depend on a remote service to display readings to clinical staff.", "questionsHTML": "<ol dir=\"ltr\"><li>Identify one asset.<\/li><li>Identify one interface.<\/li><li>Identify one dependency.<\/li><li>Identify one trust boundary.<\/li><li>What is the most important distinction between an interface and a dependency?<\/li><\/ol>", "answerOrigin": "study"}, {"id": "q-78e8519a17bca8", "type": "case", "prompt": "Smart Building Security System", "answerHTML": "<ol dir=\"ltr\"><li>Device Asset: Correct camera operation. Service Asset: Stored video recordings. Operational Asset: Availability of the monitoring service.<\/li><li>Camera / Door Sensor → Local Network → Remote Service → Web Application.<\/li><li>Web Application → Remote Service → Local Network → Controllable Device.<\/li><li>Local Network ↔ Remote Service; Web Application ↔ Remote Service. Both depend on differences in trust assumptions.<\/li><li>WHO: Security administrators and maintenance staff. WHAT: Sensor measurements, video recordings, and control commands. WHERE: Devices are deployed across several buildings, with data traveling to a remote service.<\/li><li>Device Network Interface, Remote Service Interface, and Web Application Interface.<\/li><li>Because control commands can return to devices and may affect physical behavior. Mapping only telemetry would omit those interactions.<\/li><\/ol>", "group": "42-47", "lecture": "2", "href": "lesson.html#practice-42-47", "context": "A company operates smart cameras and door sensors across several buildings. The devices send measurements and video recordings through local networks to a remote service. Security administrators use a web application to monitor the buildings and send control commands. Maintenance staff can physically access some devices.", "questionsHTML": "<ol dir=\"ltr\"><li>Identify one Device Asset, one Service Asset, and one Operational Asset.<\/li><li>Describe the Data Path.<\/li><li>Describe a possible Control Path.<\/li><li>Identify two possible Trust Boundaries.<\/li><li>Answer one WHO, one WHAT, and one WHERE question about the system.<\/li><li>Identify three interfaces.<\/li><li>Explain why drawing only the Data Path would be insufficient.<\/li><\/ol>", "answerOrigin": "source"}, {"id": "q-3da69d5b492bcf", "type": "case", "prompt": "Smart Building Access Control", "answerHTML": "<ol dir=\"ltr\"><li>Smart Lock, Gateway, Remote Service, Mobile Application, Web Dashboard.<\/li><li>Employee ↔ Mobile Application; Mobile Application ↔ Remote Service; Remote Service ↔ Gateway; Gateway ↔ Smart Lock.<\/li><li>User ↔ Application; Application ↔ Remote Service; Remote Service ↔ Gateway. These should be checked against the system&#x27;s actual trust assumptions.<\/li><li>Smart Lock Hardware and Gateway Hardware.<\/li><li>Assets: Correct Lock Operation and User Access Permissions. Dependencies: Remote Service and Gateway for the described remote-control path.<\/li><li>Employees, Installers, and Administrators.<\/li><li>The map could omit commands sent back to unlock or control the physical locks.<\/li><li>A gateway should not be considered trusted only because it is inside the local network.<\/li><li>Device Identity, Authentication, Authorization, Access Control, and Trust.<\/li><\/ol>", "group": "54-58", "lecture": "2", "href": "lesson.html#practice-54-58", "context": "A company operates smart door locks in multiple buildings. Employees use a mobile application to request access. The application communicates with a remote service, which forwards commands through local gateways to the locks. Installers can physically access the locks and gateways for maintenance. Administrators manage user access through a web dashboard.", "questionsHTML": "<ol dir=\"ltr\"><li>Identify five system components.<\/li><li>Identify four communication or interaction paths.<\/li><li>Identify three possible trust boundaries.<\/li><li>Identify two physical access points.<\/li><li>Identify two assets and two dependencies.<\/li><li>Identify two human roles.<\/li><li>What could be missing if the map shows only telemetry?<\/li><li>Why should local gateways not automatically be considered trusted?<\/li><li>Which Week 2 concepts will help analyze access decisions?<\/li><\/ol>", "answerOrigin": "source"}, {"id": "q-c22b6cff37736e", "type": "case", "prompt": "Smart Factory Monitoring System", "answerHTML": "<ol dir=\"ltr\"><li>Sensors → Local Gateway → Cloud Platform → Web Dashboard. Add Administrators and Installers, and mark physical maintenance interfaces and possible trust boundaries.<\/li><li>Sensor ↔ Gateway, Gateway ↔ local device-management functions (if present), and internal sensor maintenance access. The scenario explicitly establishes Sensor ↔ Gateway; other internal paths must be verified rather than assumed.<\/li><li>The remotely reachable Cloud Platform or Dashboard interface.<\/li><li>The sensor maintenance interface used by installers.<\/li><li>Name: Sensor Maintenance Interface. Location: Physical Sensor. Who Can Reach It: Installers. Purpose: Maintenance. Trust Change: Depends on who manages the interface and its trust context.<\/li><li>Local sensor measurement collection.<\/li><li>Cloud-based remote monitoring through the dashboard.<\/li><li>Dependencies: Gateway for forwarding measurements; Cloud Platform for remote monitoring. Possible Trust Boundaries: Sensor ↔ Gateway and Gateway ↔ Cloud, if their trust assumptions differ.<\/li><li>Internal interfaces still matter because compromise of one component may make another internal interface reachable.<\/li><\/ol>", "group": "48-53", "lecture": "2", "href": "lesson.html#practice-48-53", "context": "A factory operates 500 connected environmental sensors. Each sensor collects measurements and sends them to a local gateway. The gateway forwards the data to a cloud platform. Administrators use a web dashboard to monitor the factory. Installers can access a maintenance interface on each sensor. The cloud platform is required for remote monitoring, but sensors can continue collecting measurements locally.", "questionsHTML": "<ol dir=\"ltr\"><li>Draw a first-pass attack-surface map.<\/li><li>Identify three internal interfaces or interaction paths.<\/li><li>Identify one possible external exposure.<\/li><li>Which management interface deserves special attention?<\/li><li>Create an inventory record for the sensor maintenance interface.<\/li><li>What continues if the cloud becomes unavailable?<\/li><li>What functionality may be interrupted?<\/li><li>Identify two dependencies and two possible trust boundaries.<\/li><li>Explain why the internal network cannot automatically be considered trusted.<\/li><\/ol>", "answerOrigin": "source"}, {"id": "q-d07018f8ca9a6f", "type": "case", "prompt": "Smart Building Access System", "answerHTML": "<ol dir=\"ltr\"><li>Hardware, Firmware, Radio / Network, Gateway, Cloud / API, and Application / Human.<\/li><li>Hardware Surface.<\/li><li>Firmware Surface.<\/li><li>Radio / Network Surface.<\/li><li>The gateway connects local devices to other networks or remote services and acts as a shared communication or trust point.<\/li><li>Cloud / API Surface.<\/li><li>Because human workflows such as administration, installation, and maintenance are part of the system&#x27;s attack surface.<\/li><li>No. Interfaces indicate exposure that must be understood and managed; they do not automatically prove insecurity.<\/li><\/ol>", "group": "30-35", "lecture": "2", "href": "lesson.html#practice-30-35", "context": "A company operates smart door locks connected through a local wireless network. The devices contain embedded firmware and physical debugging interfaces. A gateway connects the locks to a cloud management service. Administrators use a web application to manage access permissions, while installers perform device maintenance.", "questionsHTML": "<ol dir=\"ltr\"><li>Identify the six attack-surface areas in this system.<\/li><li>Which area includes physical debugging interfaces?<\/li><li>Which area includes embedded code and configuration?<\/li><li>Which area includes wireless communication?<\/li><li>What is the role of the gateway?<\/li><li>Which area includes cloud management functions?<\/li><li>Why must administrators and installers be included in the attack-surface map?<\/li><li>Does the presence of these interfaces automatically prove the system is insecure?<\/li><\/ol>", "answerOrigin": "source"}, {"id": "q-9f7c67487ff346", "type": "mcq", "prompt": "What does CPS stand for?", "answerHTML": "<p>B. Cyber-Physical System<\/p><p>CPS = Cyber-Physical System.<\/p>", "group": "final", "lecture": "final", "href": "exam.html#final-mcq-1", "options": ["Cloud Processing Service", "Cyber-Physical System", "Connected Protection System", "Computer Protocol Security"], "correct": 1, "explanation": "CPS = Cyber-Physical System.", "persist": "final-mcq-1"}, {"id": "q-67ae4dc6552a9c", "type": "mcq", "prompt": "Which component interacts with the physical environment?", "answerHTML": "<p>C. Sensor or Actuator<\/p><p>Sensor بجمع معلومات من البيئة، وActuator بنفذ فعلًا فيزيائيًا.<\/p>", "group": "final", "lecture": "final", "href": "exam.html#final-mcq-2", "options": ["Cloud Storage", "Web Application", "Sensor or Actuator", "Remote Database"], "correct": 2, "explanation": "Sensor بجمع معلومات من البيئة، وActuator بنفذ فعلًا فيزيائيًا.", "persist": "final-mcq-2"}, {"id": "q-189cefc8d36d81", "type": "mcq", "prompt": "Which component may aggregate data and translate communication?", "answerHTML": "<p>A. Gateway / Edge<\/p><p>Gateway ممكن يجمع بيانات من عدة أجهزة ويكيّف الاتصال بينها وبين الخدمات.<\/p>", "group": "final", "lecture": "final", "href": "exam.html#final-mcq-3", "options": ["Gateway / Edge", "User Account", "UX", "Sensor Housing"], "correct": 0, "explanation": "Gateway ممكن يجمع بيانات من عدة أجهزة ويكيّف الاتصال بينها وبين الخدمات.", "persist": "final-mcq-3"}, {"id": "q-f19728a4694169", "type": "mcq", "prompt": "Which is a common IoT security challenge?", "answerHTML": "<p>D. Long deployment lifetime<\/p><p>Long Lifetime أحد تحديات أمن IoT؛ البيئة والدعم ممكن يتغيروا خلال تشغيل الجهاز.<\/p>", "group": "final", "lecture": "final", "href": "exam.html#final-mcq-4", "options": ["All devices have unlimited resources", "Every device has the same operating system", "Devices never change ownership", "Long deployment lifetime"], "correct": 3, "explanation": "Long Lifetime أحد تحديات أمن IoT؛ البيئة والدعم ممكن يتغيروا خلال تشغيل الجهاز.", "persist": "final-mcq-4"}, {"id": "q-de6bd9de0e49e4", "type": "mcq", "prompt": "What does OTA stand for?", "answerHTML": "<p>B. Over-the-Air<\/p><p>OTA = Over-the-Air؛ توصيل البرمجيات أو الإعدادات عن بُعد.<\/p>", "group": "final", "lecture": "final", "href": "exam.html#final-mcq-5", "options": ["Online Transfer Access", "Over-the-Air", "Open Technology Application", "Operating Trust Agreement"], "correct": 1, "explanation": "OTA = Over-the-Air؛ توصيل البرمجيات أو الإعدادات عن بُعد.", "persist": "final-mcq-5"}, {"id": "q-d9d03221ce9e64", "type": "mcq", "prompt": "Which party is responsible for hardware and embedded software decisions?", "answerHTML": "<p>C. Device Manufacturer<\/p><p>Device Manufacturer مسؤول عن قرارات Hardware وEmbedded Software.<\/p>", "group": "final", "lecture": "final", "href": "exam.html#final-mcq-6", "options": ["User", "Installer", "Device Manufacturer", "Cloud Customer"], "correct": 2, "explanation": "Device Manufacturer مسؤول عن قرارات Hardware وEmbedded Software.", "persist": "final-mcq-6"}, {"id": "q-c5bb02bc7a6ffb", "type": "mcq", "prompt": "Which direction does telemetry usually travel?", "answerHTML": "<p>A. From physical environment toward applications and services<\/p><p>Telemetry بيانات القياس والمراقبة المتجهة من البيئة الفيزيائية نحو التطبيقات والخدمات.<\/p>", "group": "final", "lecture": "final", "href": "exam.html#final-mcq-7", "options": ["From physical environment toward applications and services", "Only from cloud to actuator", "Only between users", "From application to locking mechanism"], "correct": 0, "explanation": "Telemetry بيانات القياس والمراقبة المتجهة من البيئة الفيزيائية نحو التطبيقات والخدمات.", "persist": "final-mcq-7"}, {"id": "q-a34d7687026391", "type": "mcq", "prompt": "What does UART stand for?", "answerHTML": "<p>D. Universal Asynchronous Receiver/Transmitter<\/p><p>UART = Universal Asynchronous Receiver/Transmitter.<\/p>", "group": "final", "lecture": "final", "href": "exam.html#final-mcq-8", "options": ["Universal Access Radio Technology", "Unified Application Routing Tool", "User Authentication Resource Token", "Universal Asynchronous Receiver/Transmitter"], "correct": 3, "explanation": "UART = Universal Asynchronous Receiver/Transmitter.", "persist": "final-mcq-8"}, {"id": "q-0c85246ce65dd2", "type": "mcq", "prompt": "Which term describes something valuable that must be protected or kept functioning?", "answerHTML": "<p>B. Asset<\/p><p>Asset هو شيء ذو قيمة لازم نحميه أو نحافظ على عمله.<\/p>", "group": "final", "lecture": "final", "href": "exam.html#final-mcq-9", "options": ["Interface", "Asset", "Dependency", "Gateway"], "correct": 1, "explanation": "Asset هو شيء ذو قيمة لازم نحميه أو نحافظ على عمله.", "persist": "final-mcq-9"}, {"id": "q-c1908b7f9c9b91", "type": "mcq", "prompt": "Which term describes another component or service required for correct operation?", "answerHTML": "<p>C. Dependency<\/p><p>Dependency مكوّن أو خدمة مطلوبة حتى تعمل وظيفة النظام بشكل صحيح.<\/p>", "group": "final", "lecture": "final", "href": "exam.html#final-mcq-10", "options": ["Telemetry", "Interface", "Dependency", "UX"], "correct": 2, "explanation": "Dependency مكوّن أو خدمة مطلوبة حتى تعمل وظيفة النظام بشكل صحيح.", "persist": "final-mcq-10"}, {"id": "q-e8e3591d81ec0a", "type": "mcq", "prompt": "Which of the following is a possible trust boundary?", "answerHTML": "<p>A. Mobile Application ↔ Remote Service, where trust assumptions differ<\/p><p>Trust Boundary بتظهر لما تتغير افتراضات الثقة بين منطقتين.<\/p>", "group": "final", "lecture": "final", "href": "exam.html#final-mcq-11", "options": ["Mobile Application ↔ Remote Service, where trust assumptions differ", "A device label", "A temperature value", "A processor clock"], "correct": 0, "explanation": "Trust Boundary بتظهر لما تتغير افتراضات الثقة بين منطقتين.", "persist": "final-mcq-11"}, {"id": "q-7265eab7a6c555", "type": "mcq", "prompt": "Which is a management interface?", "answerHTML": "<p>D. A diagnostics interface<\/p><p>Diagnostics Interface واجهة للفحص والتشخيص، وهي من واجهات الإدارة.<\/p>", "group": "final", "lecture": "final", "href": "exam.html#final-mcq-12", "options": ["A temperature reading", "A camera lens", "A device battery", "A diagnostics interface"], "correct": 3, "explanation": "Diagnostics Interface واجهة للفحص والتشخيص، وهي من واجهات الإدارة.", "persist": "final-mcq-12"}, {"id": "q-f2de6fc64b29b2", "type": "mcq", "prompt": "What should an attack-surface map include?", "answerHTML": "<p>C. Data and control paths<\/p><p>الخريطة بتشمل البيانات الخارجة والأوامر الراجعة للجهاز، مع المكونات والواجهات والاعتمادات وحدود الثقة.<\/p>", "group": "final", "lecture": "final", "href": "exam.html#final-mcq-13", "options": ["Only vulnerabilities", "Only network ports", "Data and control paths", "Only cloud services"], "correct": 2, "explanation": "الخريطة بتشمل البيانات الخارجة والأوامر الراجعة للجهاز، مع المكونات والواجهات والاعتمادات وحدود الثقة.", "persist": "final-mcq-13"}, {"id": "q-08fe6fed4e99d7", "type": "mcq", "prompt": "Which statement is correct?", "answerHTML": "<p>B. Internal does not automatically mean trusted<\/p><p>وجود الواجهة داخل النظام لا يكفي وحده لاعتبارها موثوقة.<\/p>", "group": "final", "lecture": "final", "href": "exam.html#final-mcq-14", "options": ["All internal interfaces are trusted", "Internal does not automatically mean trusted", "Every gateway is optional in all systems", "IoT security concerns only the device"], "correct": 1, "explanation": "وجود الواجهة داخل النظام لا يكفي وحده لاعتبارها موثوقة.", "persist": "final-mcq-14"}, {"id": "q-5fbb3157a797c1", "type": "mcq", "prompt": "What is the first step in attack-surface mapping?", "answerHTML": "<p>A. Draw the physical device and its purpose<\/p><p>الخطوة الأولى من Slide 49: Draw the physical device and its purpose.<\/p>", "group": "final", "lecture": "final", "href": "exam.html#final-mcq-15", "options": ["Draw the physical device and its purpose", "Identify specific attacks", "Choose an encryption algorithm", "Remove the cloud"], "correct": 0, "explanation": "الخطوة الأولى من Slide 49: Draw the physical device and its purpose.", "persist": "final-mcq-15"}, {"id": "q-c70414d0010b7f", "type": "blank", "prompt": "IoT stands for Internet of _______.", "answerHTML": "<p>Things<\/p><p>IoT = Internet of Things.<\/p>", "group": "final", "lecture": "final", "href": "exam.html#final-blank-1", "answer": "Things"}, {"id": "q-cf904cb21a3e1f", "type": "blank", "prompt": "API stands for Application Programming _______.", "answerHTML": "<p>Interface<\/p><p>واجهة تواصل بين مكونات أو خدمات برمجية.<\/p>", "group": "final", "lecture": "final", "href": "exam.html#final-blank-2", "answer": "Interface"}, {"id": "q-1ef46c8f46f850", "type": "blank", "prompt": "UX stands for User _______.", "answerHTML": "<p>Experience<\/p><p>بتتعلق بكيفية تفاعل الأشخاص مع المنتج وخطوات استخدامه.<\/p>", "group": "final", "lecture": "final", "href": "exam.html#final-blank-3", "answer": "Experience"}, {"id": "q-4a087cd7d27ec3", "type": "blank", "prompt": "A _______ connects local devices to external networks or services.", "answerHTML": "<p>gateway<\/p><p>ممكن يربط الأجهزة المحلية بالخدمات الخارجية.<\/p>", "group": "final", "lecture": "final", "href": "exam.html#final-blank-4", "answer": "gateway"}, {"id": "q-250bcf08a57949", "type": "blank", "prompt": "A _______ is a point through which a component communicates or can be accessed.", "answerHTML": "<p>interface<\/p><p>هذا تعريف Interface.<\/p>", "group": "final", "lecture": "final", "href": "exam.html#final-blank-5", "answer": "interface"}, {"id": "q-e40dfd6849cb85", "type": "blank", "prompt": "A trust boundary involves different trust _______.", "answerHTML": "<p>assumptions<\/p><p>الاختلاف في Trust Assumptions هو الأساس.<\/p>", "group": "final", "lecture": "final", "href": "exam.html#final-blank-6", "answer": "assumptions"}, {"id": "q-2db4efe1673f63", "type": "blank", "prompt": "Connected devices exchange data and _______ through communication paths.", "answerHTML": "<p>commands<\/p><p>الاتصالات بتنقل بيانات وأوامر.<\/p>", "group": "final", "lecture": "final", "href": "exam.html#final-blank-7", "answer": "commands"}, {"id": "q-1107793bbd1f82", "type": "blank", "prompt": "The three questions for every component are Who, What, and _______.", "answerHTML": "<p>Where<\/p><p>Who–What–Where هي الأسئلة الثلاثة لكل مكوّن.<\/p>", "group": "final", "lecture": "final", "href": "exam.html#final-blank-8", "answer": "Where"}, {"id": "q-3501dcadc2d0b1", "type": "blank", "prompt": "Internal does not automatically mean _______.", "answerHTML": "<p>trusted<\/p><p>وجود الواجهة داخل النظام مش دليل ثقة تلقائي.<\/p>", "group": "final", "lecture": "final", "href": "exam.html#final-blank-9", "answer": "trusted"}, {"id": "q-443113fa948aee", "type": "blank", "prompt": "Dependency mapping separates essential operation from _______ features.", "answerHTML": "<p>convenience<\/p><p>Essential Operation مقابل Convenience Features.<\/p>", "group": "final", "lecture": "final", "href": "exam.html#final-blank-10", "answer": "convenience"}, {"id": "q-2359ba5ccada7e", "type": "short", "prompt": "List THREE differences between Traditional IT and IoT.", "answerHTML": "<pre dir=\"ltr\">1. Traditional IT uses general-purpose computers; IoT often uses special-purpose devices.\n2. Traditional IT has frequent user interaction; IoT devices are often unattended.\n3. Traditional IT systems are usually easier to patch or replace; IoT devices may have long deployment lifetimes.<\/pre><p>احفظ ثلاث مقارنات من Slide 12، وكل نقطة واضحة لحالها.<\/p>", "group": "final", "lecture": "final", "href": "exam.html#final-short-1"}, {"id": "q-4e53c055858b90", "type": "short", "prompt": "Mention THREE IoT security challenges.", "answerHTML": "<pre dir=\"ltr\">Constraints, Physical Exposure, and Scale.<\/pre><p>كمان ممكن تذكر Heterogeneity أو Long Lifetime أو Dependencies.<\/p>", "group": "final", "lecture": "final", "href": "exam.html#final-short-2"}, {"id": "q-57ae740eb4aa12", "type": "short", "prompt": "List THREE responsibilities in an IoT ecosystem and the responsible party.", "answerHTML": "<pre dir=\"ltr\">1. Device Manufacturer — Hardware and embedded software decisions.\n2. Service Provider — Backend, remote management, and accounts.\n3. Installer / Organization — Deployment, network placement, and configuration.<\/pre><p>Slide 23: اربط كل جهة بمسؤوليتها، وممكن تذكر User / Operator كمان.<\/p>", "group": "final", "lecture": "final", "href": "exam.html#final-short-3"}, {"id": "q-b58e2fe60336e0", "type": "short", "prompt": "List the FIVE fields of an Attack Surface Inventory.", "answerHTML": "<pre dir=\"ltr\">Component or Interface Name; Location; Who Can Reach It; Purpose; Trust Change.<\/pre><p>هاي قائمة Slide 50، مهمة للحفظ.<\/p>", "group": "final", "lecture": "final", "href": "exam.html#final-short-4"}, {"id": "q-63060b24c921c3", "type": "short", "prompt": "Mention THREE common attack-surface mapping mistakes.", "answerHTML": "<pre dir=\"ltr\">1. Looking only for open network ports.\n2. Drawing only data flow and forgetting control commands.\n3. Assuming internal components are automatically trusted.<\/pre><p>كلها موجودة في Slide 55. ممكن بدل أي نقطة تذكر تجاهل الأشخاص أو البدء بالثغرات.<\/p>", "group": "final", "lecture": "final", "href": "exam.html#final-short-5"}, {"id": "q-a408e224ce31de", "type": "case", "prompt": "Smart Camera", "answerHTML": "<ol dir=\"ltr\"><li>Smart Camera, Home Network, Cloud Service, Mobile Application.<\/li><li>Video Recordings.<\/li><li>Cloud Service for remote recording access.<\/li><li>Camera Network Interface or Mobile Application Interface.<\/li><li>Mobile Application ↔ Cloud Service, if trust assumptions differ.<\/li><\/ol><p>الـAsset هو الشيء المهم، والـDependency شيء النظام بيعتمد عليه، والـInterface نقطة تواصل، والـTrust Boundary مكان اختلاف افتراضات الثقة.<\/p>", "group": "final", "lecture": "final", "href": "exam.html#final-case-1", "context": "A smart camera records video, connects to a home network, stores recordings in a remote cloud service, and allows the owner to view recordings using a mobile application.", "questionsHTML": "<ol dir=\"ltr\"><li>Identify four ecosystem components.<\/li><li>Identify one asset.<\/li><li>Identify one dependency.<\/li><li>Identify one interface.<\/li><li>Identify one possible trust boundary.<\/li><\/ol>"}, {"id": "q-6d0aa94acb4038", "type": "case", "prompt": "Connected Medical Sensor", "answerHTML": "<ol dir=\"ltr\"><li>Medical Sensor.<\/li><li>Patient Measurements.<\/li><li>Sensor → Communication Path → Remote Service → Clinical Staff.<\/li><li>Remote Service for displaying patient readings.<\/li><li>Clinical staff may lose access to remote readings. Local measurement may continue if the device supports it.<\/li><\/ol><p>ما بنفترض إنه الجهاز توقف تمامًا، لأن استمرار القياس المحلي بيعتمد على تصميمه.<\/p>", "group": "final", "lecture": "final", "href": "exam.html#final-case-2", "context": "A connected medical sensor measures patient data and sends readings to a remote service used by clinical staff.", "questionsHTML": "<ol dir=\"ltr\"><li>What is the physical device?<\/li><li>What is the main data asset?<\/li><li>What is the Data Path?<\/li><li>Identify one dependency.<\/li><li>What may happen if the remote service becomes unavailable?<\/li><\/ol>"}, {"id": "q-1eb8da2610fb66", "type": "diagram", "prompt": "Draw a simple attack-surface map for a smart thermostat. Your diagram must include the thermostat, local network, remote service, mobile application, and user. Show the Data Path, Control Path, and possible Trust Boundaries.", "answerHTML": "<div class=\"course-flow\" dir=\"ltr\"><span>User + Mobile Application<\/span><b>↔<\/b><span>Remote Service<\/span><b>↔<\/b><span>Local Network<\/span><b>↔<\/b><span>Smart Thermostat<\/span><\/div><p dir=\"ltr\"><b>Data Path:<\/b> Thermostat → Local Network → Remote Service → Mobile Application.<\/p><p dir=\"ltr\"><b>Control Path:<\/b> Mobile Application → Remote Service → Local Network → Thermostat.<\/p><p dir=\"ltr\"><b>Assets:<\/b> Temperature Measurements, Correct Thermostat Operation, Service Availability.<\/p><p dir=\"ltr\"><b>Possible Trust Boundaries:<\/b> Application ↔ Remote Service and Local Network ↔ Remote Service, where trust assumptions differ.<\/p>", "group": "final", "lecture": "final", "href": "exam.html#final-diagram"}, {"id": "q-e9ae4849631219", "type": "mcq", "prompt": "What does IoT stand for?", "answerHTML": "<p>B. Internet of Things<\/p><p>IoT = Internet of Things.<\/p>", "group": "mini", "lecture": "final", "href": "exam.html#mini-practice", "options": ["Internet of Technology", "Internet of Things", "Integration of Tools", "Internet of Telecommunications"], "correct": 1, "explanation": "IoT = Internet of Things.", "persist": "mini-direct-q1"}, {"id": "q-af00c3aa1b8b82", "type": "mcq", "prompt": "Which component collects information from the physical environment?", "answerHTML": "<p>A. Sensor<\/p><p>Sensor بقرأ المعلومات من البيئة الفيزيائية.<\/p>", "group": "mini", "lecture": "final", "href": "exam.html#mini-practice", "options": ["Sensor", "Cloud", "Application", "Gateway"], "correct": 0, "explanation": "Sensor بقرأ المعلومات من البيئة الفيزيائية.", "persist": "mini-direct-q2"}, {"id": "q-10c351afeac809", "type": "mcq", "prompt": "What does API stand for?", "answerHTML": "<p>A. Application Programming Interface<\/p><p>API = Application Programming Interface.<\/p>", "group": "mini", "lecture": "final", "href": "exam.html#mini-practice", "options": ["Application Programming Interface", "Automatic Protection Interface", "Advanced Program Integration", "Application Physical Interface"], "correct": 0, "explanation": "API = Application Programming Interface.", "persist": "mini-direct-q3"}, {"id": "q-ef1d3de785bb4c", "type": "mcq", "prompt": "Which of the following is a Trust Boundary?", "answerHTML": "<p>C. A point where trust assumptions change<\/p><p>هي نقطة انتقال بين مناطق بافتراضات ثقة مختلفة.<\/p>", "group": "mini", "lecture": "final", "href": "exam.html#mini-practice", "options": ["A device battery", "A sensor reading", "A point where trust assumptions change", "A device model number"], "correct": 2, "explanation": "هي نقطة انتقال بين مناطق بافتراضات ثقة مختلفة.", "persist": "mini-direct-q4"}, {"id": "q-583df762fc4b46", "type": "mcq", "prompt": "Which path carries commands toward the physical device?", "answerHTML": "<p>B. Control Path<\/p><p>Control Path بنقل أوامر التحكم باتجاه الجهاز.<\/p>", "group": "mini", "lecture": "final", "href": "exam.html#mini-practice", "options": ["Data Path", "Control Path", "Storage Path", "Inventory Path"], "correct": 1, "explanation": "Control Path بنقل أوامر التحكم باتجاه الجهاز.", "persist": "mini-direct-q5"}, {"id": "q-d751245f3c4810", "type": "mcq", "prompt": "Which is a common mistake in attack-surface mapping?", "answerHTML": "<p>D. Looking only for open ports<\/p><p>التركيز على Open Ports فقط خطأ؛ لازم تشمل كل الواجهات.<\/p>", "group": "mini", "lecture": "final", "href": "exam.html#mini-practice", "options": ["Including users", "Mapping dependencies", "Drawing both data and control paths", "Looking only for open ports"], "correct": 3, "explanation": "التركيز على Open Ports فقط خطأ؛ لازم تشمل كل الواجهات.", "persist": "mini-direct-q6"}];